insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f077','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Pyrite FeS2 is cubic and pale brass-yellow, with a greenish-black streak, hardness 6-6.5 and specific gravity 5.0. It forms striated cubes and pyritohedra and is called fool''s gold.','It is too hard for a knife to scratch, which is unusual for a sulphide. Real gold is soft, bends, and gives a golden streak. Pyrite is used for sulphuric acid, not as an iron ore.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,3,1,942) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f078','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Chalcopyrite CuFeS2 is tetragonal, deep brass-yellow and often tarnished, with a greenish-black streak and hardness 3.5-4. It is the most important ore of copper (34.6% Cu).','A knife scratches chalcopyrite but not pyrite. It is the main ore mineral at Khetri (Rajasthan), Malanjkhand (Madhya Pradesh) and Singhbhum (Jharkhand).','Kerala PSC HSST Geology 2026 (QP 80/2026/OL)',true,3,1,943) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f079','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Galena PbS is cubic and lead-grey with bright metallic lustre, perfect cubic cleavage, hardness 2.5 and very high specific gravity (about 7.5). It is the chief ore of lead and often carries silver.','It breaks into tiny cubes because it has the same structure as halite. In India it is mined with sphalerite at Zawar and Rampura-Agucha, Rajasthan.',null,true,3,1,944) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f080','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Sphalerite ZnS (zinc blende) is cubic, with resinous to adamantine lustre, perfect dodecahedral cleavage in six directions, hardness 3.5-4 and a streak paler than its body colour. It is the chief ore of zinc.','Iron-rich sphalerite is black (''black jack'') yet still gives a pale brown streak. Its hexagonal polymorph is wurtzite. It commonly occurs with galena.',null,true,3,1,945) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f081','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Other sulphides: cinnabar HgS (red, mercury ore), molybdenite MoS2 (soft, greasy), stibnite Sb2S3 (antimony), argentite Ag2S (silver), realgar AsS (red), orpiment As2S3 (yellow), pentlandite (nickel), pyrrhotite Fe1-xS (magnetic).','Sulphides are mostly soft, heavy, metallic ore minerals. Pyrrhotite is the one common magnetic sulphide; marcasite is the orthorhombic polymorph of pyrite.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,2,2,946) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f082','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Halite NaCl (rock salt) is cubic, with perfect cubic cleavage, hardness 2.5, specific gravity 2.16 and a salty taste. It dissolves in water and forms in evaporite deposits.','Evaporite means a rock left behind when salty water dries up. Because it is light and flows, buried salt rises as salt domes. India mines rock salt at Mandi, Himachal Pradesh.',null,true,3,1,947) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f083','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Fluorite CaF2 is cubic and commonly forms cubes, but its perfect cleavage is octahedral (four directions). Hardness is 4 and specific gravity 3.18; it is used as a flux in steel making.','The word fluorescence comes from fluorite, which often glows under ultraviolet light. India''s main fluorite deposit is at Amba Dongar, Gujarat.','Goa PSC Assistant Professor (Geology) 2021',true,3,1,948) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f084','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Other halide minerals: sylvite KCl (bitter taste, potash source), carnallite KMgCl3.6H2O (potash evaporite) and cryolite Na3AlF6 (flux in aluminium smelting, from Ivigtut, Greenland).','Halides are compounds of metals with chlorine or fluorine. Most are soft, light, and many dissolve in water. Sylvite looks like halite but tastes bitter.',null,true,2,2,949) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f001','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','A polarising (petrological) microscope has two polarising filters: the polariser below the stage and the analyser above the objective, with their vibration directions at 90° to each other.','The lower filter makes light vibrate in one plane. The upper one tests what the mineral did to that light. With no mineral in between, the crossed filters give darkness.',null,true,3,1,950) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f002','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','In plane polarised light (analyser out) we study colour, pleochroism, relief, cleavage and form; under crossed polars (analyser in) we study interference colours, extinction and twinning.','Hook: plane light shows what the mineral looks like; crossed polars show what the mineral does to light.',null,true,3,1,951) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f003','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','The Bertrand lens is inserted, together with the condenser and a high-power objective, to see interference figures (conoscopic view).','Conoscopic means using a cone of converging light. The interference figure forms at the back of the objective, and the Bertrand lens brings it into focus for the eye.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,952) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f004','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','A Nicol prism is clear calcite (Iceland spar) cut and re-cemented with Canada balsam; the ordinary ray is totally reflected away and the extraordinary ray passes through as polarised light.','Calcite splits light into two rays. The balsam has a lower index than the ordinary ray, so that ray is thrown out sideways. Hook: O = Out, E = Emerges.',null,true,3,1,953) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f005','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','A standard rock thin section is 0.03 mm (30 micrometres) thick and is mounted in a medium of refractive index about 1.54 (Canada balsam).','Interference colour depends on thickness, so one fixed thickness lets us compare minerals. Quartz (first-order grey to white at 0.03 mm) is the usual thickness check.',null,true,3,1,954) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f006','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Refractive index (n) is the speed of light in vacuum divided by its speed in the mineral; a higher index means light travels more slowly in the mineral.','Example: n = 1.5 means light moves at 3 × 10^8 / 1.5 = 2 × 10^8 m/s inside the mineral. Dense minerals usually have higher indices.',null,true,2,2,955) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f007','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Relief is how strongly a mineral''s outline stands out in plane polarised light; it depends on the difference between the refractive indices of the mineral and the mounting medium.','Big difference = bold dark borders and a rough-looking surface (garnet, zircon). Small difference = the grain is almost invisible (quartz in balsam).',null,true,3,1,956) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f008','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','The Becke line is a bright line at a grain edge that moves into the material of higher refractive index when the stage is lowered (focus raised).','Hook: ''Lower the stage, the line goes to the Higher index.'' It tells whether the mineral''s index is above or below that of the balsam.',null,true,3,1,957) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f009','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Minerals with index above the balsam show positive relief (garnet, olivine, zircon); those with index below it show negative relief (fluorite, sodalite, opal).','Fluorite (n = 1.434) is the classic negative-relief mineral. Positive or negative is decided with the Becke line, not by eye alone.',null,true,2,2,958) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f010','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Calcite ''twinkles'': its relief changes from high to low as the stage is rotated in plane polarised light, because its two indices (1.658 and 1.486) are very different.','One index is well above the balsam and the other is below it. So the grain looks bold in one position and faint 90° away.',null,true,2,2,959) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f011','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','Isotropic substances - cubic minerals (garnet, spinel, fluorite) and glass - have a single refractive index and stay dark under crossed polars through a full rotation of the stage.','Light travels at the same speed in every direction, so it is not split into two rays. Nothing gets through the analyser.','IIT JAM Geology 2018',true,3,1,960) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f012','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','Anisotropic minerals split light into two rays that vibrate at right angles to each other and travel at different speeds; this is double refraction, seen best in Iceland spar (calcite).','A dot seen through clear calcite looks double. The speed difference between the two rays is what later produces interference colours.',null,true,3,1,961) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f013','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','Cubic crystals are isotropic; tetragonal, hexagonal and trigonal crystals are uniaxial; orthorhombic, monoclinic and triclinic crystals are biaxial.','One special axis (3-, 4- or 6-fold) gives one optic axis. Lower symmetry gives two optic axes. The highest (cubic) symmetry gives no special direction at all.','IIT JAM Geology 2018',true,3,1,962) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f014','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','A uniaxial mineral has one optic axis, parallel to the c crystallographic axis, and two principal indices: omega (ω, ordinary ray) and epsilon (ε, extraordinary ray).','The ordinary ray vibrates at right angles to c and always has index ω. The extraordinary ray''s index changes with direction and reaches ε when it vibrates parallel to c.',null,true,3,1,963) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f015','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','Along an optic axis there is no double refraction, so a section cut perpendicular to it (such as a basal section of quartz) stays dark under crossed polars.','Looking down the optic axis the mineral behaves like an isotropic one. This same section gives the centred optic-axis interference figure.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,964) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f016','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','Uniaxial positive means ε > ω (quartz, zircon, rutile); uniaxial negative means ε < ω (calcite, tourmaline, apatite, beryl, nepheline, corundum).','Hook: quartz is positive, calcite is negative. Most other common uniaxial rock-forming minerals are negative.',null,true,3,1,965) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f017','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','A biaxial mineral has three principal indices alpha < beta < gamma, for light vibrating along X, Y and Z; its two optic axes lie in the XZ plane (optic axial plane).','Y, the beta direction, is at right angles to the optic plane and is called the optic normal.',null,true,3,1,966) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f018','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','2V is the angle between the two optic axes; the mineral is biaxial positive if Z is the acute bisectrix and biaxial negative if X is the acute bisectrix.','Acute bisectrix = the line that halves the smaller angle between the optic axes. In positive minerals beta is closer to alpha; in negative ones beta is closer to gamma.',null,true,3,1,967) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f019','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','The optical indicatrix is a sphere for isotropic minerals, an ellipsoid of revolution for uniaxial minerals and a triaxial ellipsoid for biaxial minerals.','Indicatrix = a 3-D shape whose radius in any direction equals the refractive index for light vibrating in that direction.',null,true,3,1,968) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f020','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','The uniaxial positive indicatrix is prolate (stretched along the optic axis, like an egg); the uniaxial negative indicatrix is oblate (flattened along it, like a pumpkin).','In positive minerals ε, the index measured along c, is the larger one, so the shape is long along c. In negative minerals ε is the smaller one.',null,true,2,2,969) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f021','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','Birefringence is the difference between the largest and smallest refractive indices of a mineral: the difference between ε and ω for uniaxial minerals, and gamma minus alpha for biaxial minerals.','It measures how strongly the mineral splits light. A grain shows this maximum only when cut parallel to the optic axis (uniaxial) or to the optic plane (biaxial).',null,true,3,1,970) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f022','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','Retardation = thickness × birefringence. A 30 micrometre (30,000 nm) quartz section with birefringence 0.009 gives 270 nm, a first-order white.','Retardation is the distance by which the slow ray lags behind the fast ray. Keep thickness and retardation in the same unit (nm) when calculating.',null,true,3,1,971) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f023','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','The Michel-Lévy chart links section thickness, birefringence and retardation (interference colour); each colour order spans about 550 nm and ends in a red band.','Know any two of the three and read off the third. First order has greys, white, yellow and red; blues and greens start only in the second order.',null,true,3,1,972) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f024','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','In a standard section quartz and feldspars show first-order greys and whites (about 0.007-0.010); olivine and muscovite show bright second- to third-order colours; calcite (0.172) shows high-order pearly whites.','Low birefringence = dull greys. High = bright rainbow colours. Very high = washed-out creamy white, because many colours overlap.',null,true,3,1,973) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f025','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','Chlorite often shows anomalous interference colours (inky ''Berlin blue'' or brown) that are not on the Michel-Lévy chart; zoisite and clinozoisite also show anomalous blues.','Their birefringence is different for different colours of light. So the normal first-order grey is replaced by an odd blue or brown.',null,true,2,2,974) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f026','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','Accessory plates: the gypsum plate (sensitive tint, first-order red) adds about 550 nm; the mica plate adds a quarter wavelength (about 150 nm); the quartz wedge gives variable retardation.','They are pushed in at 45° to the polarisers. Their slow direction is marked, so they reveal the slow direction of the mineral and the order of its colour.',null,true,3,1,975) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f027','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','With an accessory plate, interference colours rise (addition) when the slow directions of mineral and plate are parallel, and fall (subtraction) when slow lies over fast.','Example with the gypsum plate: a 150 nm grey grain becomes 700 nm (second-order blue) on addition and 400 nm (first-order yellow) on subtraction.',null,true,3,1,976) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f028','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','A mineral is length-slow (positive elongation) if the slow ray vibrates parallel to its length and length-fast (negative elongation) if the fast ray does; sillimanite is length-slow, andalusite and tourmaline are length-fast.','It is found with the gypsum plate on an elongate grain turned to 45°. It quickly separates look-alike prismatic minerals.',null,true,2,2,977) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f029','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','A centred uniaxial optic-axis figure is a black cross (isogyres) with circular colour rings (isochromes) that stays fixed on rotation; its centre, where the optic axis emerges, is the melatope.','Thicker sections or higher birefringence give more colour rings. A cross that never breaks up on rotation means the mineral is uniaxial.','IIT JAM Geology 2018',true,3,1,978) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f030','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','In a uniaxial optic-axis figure with the gypsum plate (slow direction NE-SW), a positive mineral shows blue in the NE and SW quadrants and yellow in the NW and SE quadrants; a negative mineral shows the reverse.','Blue means addition and yellow means subtraction. The extraordinary ray vibrates radially, and in positive minerals that radial direction is the slow one.',null,true,2,2,979) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f031','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','A biaxial acute-bisectrix figure shows a cross that splits into two curved isogyres (hyperbolas) on rotation; their separation at the 45° position increases with 2V.','The two melatopes mark the two optic axes. A uniaxial cross never splits - that is the quick uniaxial versus biaxial test.',null,true,3,1,980) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f032','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','A centred biaxial optic-axis figure shows a single isogyre, straight when 2V is 90° and strongly curved when 2V is small; with an accessory plate it gives the optic sign.','The convex side of the curved isogyre points towards the acute bisectrix. This figure comes from grains showing the lowest interference colours.','GATE Geology (GG) 2024',true,2,2,981) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f033','geological-assistant','geological-assistant-m3','Extinction angles','Under crossed polars an anisotropic grain goes dark (extinct) four times in a 360° rotation, at 90° intervals, when its vibration directions are parallel to the polariser and analyser.','In those positions light passes through the grain unchanged and the analyser blocks it. The grain is brightest at 45° from extinction.',null,true,3,1,982) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f034','geological-assistant','geological-assistant-m3','Extinction angles','Extinction types: parallel (straight) - dark when cleavage or length is parallel to a cross-hair; oblique (inclined) - dark at an angle to it; symmetrical - cross-hairs bisect the angle between two cleavages.','Symmetrical extinction is seen in basal sections of amphibole and pyroxene and in calcite rhombs, where two cleavage sets cross.',null,true,3,1,983) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f035','geological-assistant','geological-assistant-m3','Extinction angles','Undulose (wavy) extinction is a dark shadow that sweeps across a single grain during rotation; it is typical of strained quartz in deformed rocks.','Stress bends the crystal lattice, so different parts of one grain go dark at slightly different positions.',null,true,3,1,984) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f036','geological-assistant','geological-assistant-m3','Extinction angles','The extinction angle is the angle between a crystal direction (cleavage trace, length or twin plane) and the nearest extinction position, commonly quoted as Z^c or X^c.','To measure: put the cleavage along a cross-hair and note the stage reading, rotate to darkness and note again. The difference is the extinction angle.',null,true,3,1,985) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f037','geological-assistant','geological-assistant-m3','Extinction angles','Prismatic sections of tetragonal, hexagonal and orthorhombic minerals give parallel extinction; monoclinic minerals give oblique extinction in most sections; triclinic minerals give oblique extinction in all sections.','In higher-symmetry crystals the vibration directions line up with the crystal axes. In monoclinic crystals only the b axis is fixed, so the largest angle is seen on the (010) section.',null,true,3,1,986) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f038','geological-assistant','geological-assistant-m3','Extinction angles','Maximum extinction angle (Z^c): clinopyroxene such as augite about 35°-48°; hornblende about 12°-30°; orthopyroxenes (enstatite, hypersthene) show parallel extinction.','Hook: pyroxene = big angle (near 45°); amphibole = small angle; orthopyroxene = zero, because it is orthorhombic.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,987) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f039','geological-assistant','geological-assistant-m3','Extinction angles','The Michel-Lévy method finds plagioclase composition (anorthite %) from the maximum symmetrical extinction angle of albite twin lamellae in sections cut perpendicular to (010).','In such sections the two sets of lamellae go dark at nearly equal angles to the left and right. Average the two, repeat on several grains and use the largest value on the curve.',null,true,3,1,988) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f040','geological-assistant','geological-assistant-m3','Extinction angles','In the Michel-Lévy method, extinction angles below about 20° are ambiguous (sodic or intermediate plagioclase); the Becke line settles it, because albite and sodic oligoclase have indices below balsam.','The curve falls from about 16° at pure albite to 0° near An20 and then rises again. So one small angle fits two different compositions.',null,false,2,2,989) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f041','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','In plagioclase the refractive indices rise steadily from albite (about 1.53) to anorthite (about 1.58) as calcium increases; extinction angle and 2V also vary with composition.','Because the change is steady, optics alone can give the composition of a plagioclase without a chemical analysis.',null,true,3,1,990) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f042','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','In olivine, refractive indices and birefringence rise with iron content; magnesian forsterite is biaxial positive (2V near 90°) while iron-rich fayalite is biaxial negative (2V about 50°).','Iron raises the indices of most ferromagnesian minerals. The sign changes at roughly Fo85-90, so common rock olivine has 2V close to 90°.',null,true,3,1,991) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f043','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','In orthopyroxenes, indices and pleochroism increase with iron: enstatite is colourless and optically positive, while hypersthene is pleochroic (pink to green) and optically negative.','The same rule holds widely: iron and titanium raise the index and deepen the colour. Compare colourless tremolite with green hornblende, or pale phlogopite with dark biotite.',null,true,2,2,992) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f044','geological-assistant','geological-assistant-m3','Pleochroism','Pleochroism is the change in colour of a mineral as the stage is rotated in plane polarised light, caused by unequal absorption of light along different vibration directions.','It is seen with the analyser out. Colour changes under crossed polars are interference colours, which is a different thing.','IIT JAM Geology 2018',true,3,1,993) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f045','geological-assistant','geological-assistant-m3','Pleochroism','Isotropic minerals are never pleochroic; coloured uniaxial minerals can show two extreme colours (dichroism) and coloured biaxial minerals three (trichroism).','One index = one colour. Two principal vibration directions (ω, ε) = two colours. Three (X, Y, Z) = three colours.',null,true,3,1,994) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f046','geological-assistant','geological-assistant-m3','Pleochroism','Biotite is darkest when its cleavage is parallel to the polariser''s vibration direction; tourmaline is darkest when its length is perpendicular to that direction.','This opposite behaviour separates the two common brown pleochroic minerals. Biotite is so reliable that it is used to find the polariser direction of a microscope.',null,true,3,1,995) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f047','geological-assistant','geological-assistant-m3','Pleochroism','Pleochroic haloes are dark, strongly pleochroic spots around tiny radioactive inclusions such as zircon, monazite and allanite, seen mainly in biotite and also in cordierite (yellow haloes).','Alpha particles from uranium and thorium damage the host mineral in a small sphere around the inclusion. Monazite, the thorium mineral of Kerala''s beach sands, is one such inclusion.',null,true,3,1,996) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f048','geological-assistant','geological-assistant-m3','Pleochroism','Diagnostic pleochroism: hypersthene pink to pale green; glaucophane lavender to blue; staurolite colourless to golden yellow; andalusite weak patchy pink; piemontite yellow-red-violet.','These colour schemes are almost fingerprints. Piemontite is the manganese-bearing epidote; glaucophane is the blue amphibole of blueschists.',null,true,2,2,997) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f049','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Quartz in thin section is colourless, clear and unaltered, with low relief, no cleavage and no visible twinning; it is uniaxial positive with first-order grey to white colours.','Feldspars look similar but show cleavage, twinning and cloudy alteration. Quartz stays ''clean''.',null,true,3,1,998) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f050','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Orthoclase has low negative relief, cloudy (kaolinised) alteration and simple Carlsbad twins; microcline shows cross-hatched twinning; sanidine is clear with a small 2V and occurs in volcanic rocks.','All three are potassium feldspars with first-order grey colours and indices below balsam. The twinning and the rock type tell them apart.',null,true,3,1,999) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f051','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Plagioclase is recognised by polysynthetic albite twinning - parallel light and dark stripes under crossed polars - and often shows compositional zoning in volcanic rocks.','Polysynthetic = many thin twin slabs repeated side by side. Alternate slabs go dark at different positions, giving the striped look.',null,true,3,1,1000) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f052','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Olivine is colourless with high relief, curved irregular cracks, no good cleavage, parallel extinction and bright second- to third-order colours; it alters to serpentine or iddingsite along the cracks.','Hook: ''cracked, clean and colourful''. Augite, its usual neighbour, has cleavage, oblique extinction and lower colours.',null,true,3,1,1001) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f053','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Augite is pale and weakly pleochroic with two cleavages near 90° (87° and 93°) in basal sections; hornblende is strongly pleochroic green-brown with cleavages at 56° and 124°.','Pyroxene = single silicate chains, nearly square cleavage. Amphibole = double chains, diamond-shaped cleavage. Add the extinction angle and the two are easily separated.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,1002) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f054','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Micas show one perfect cleavage, parallel extinction and mottled ''bird''s-eye'' extinction; muscovite is colourless with 2V of 30°-45°, while biotite is brown, strongly pleochroic and nearly uniaxial (2V 0°-25°).','Bird''s-eye = a speckled, pebbly look near the extinction position. Both micas are optically negative with bright second- to third-order colours.',null,true,3,1,1003) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f055','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Garnet is isotropic with very high relief, no cleavage and irregular fractures; it is colourless to pale pink in plane light and stays black under crossed polars.','Garnet is cubic, so it has one refractive index. High relief plus permanent darkness is the giveaway.',null,true,3,1,1004) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f056','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Calcite is uniaxial negative with extreme birefringence (0.172), rhombohedral cleavage, lamellar twinning and high-order pearl-grey to creamy interference colours.','It is also the ''twinkling'' mineral. No common silicate has such high birefringence, so the pale high-order colours point to a carbonate.',null,true,3,1,1005) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f057','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Al2SiO5 minerals: kyanite - high relief, oblique extinction up to about 30°; sillimanite - slender needles, parallel extinction, length-slow, small positive 2V; andalusite - parallel extinction, length-fast, optically negative.','Kyanite is triclinic, so its extinction is inclined. The other two are orthorhombic and are separated by the sign of elongation. Sillimanite is the needle mineral of Kerala''s khondalites.',null,true,3,1,1006) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f058','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Tourmaline is uniaxial negative and strongly pleochroic, with parallel extinction, negative elongation (length-fast), poor cleavage and rounded triangular basal sections.','It can look like biotite or hornblende, but it has no good cleavage and is darkest when its length lies across the polariser direction.',null,true,2,2,1007) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f059','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Accessory minerals: zircon - tiny prisms, very high relief, third-order or higher colours, uniaxial positive; apatite - moderate relief, first-order grey, uniaxial negative; sphene - wedge-shaped, extreme relief and birefringence.','Zircon is bright, apatite is dull grey. Sphene (titanite) is brownish with a typical diamond or wedge outline.',null,true,2,2,1008) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f060','geological-assistant','geological-assistant-m3','Twinned crystals','A twin is a symmetrical intergrowth of two or more crystals of the same mineral, related by a twin law: reflection across a twin plane, rotation about a twin axis, or inversion through a twin centre.','A twin plane can never be a symmetry plane of the single crystal. If it were, the two parts would simply be one and the same crystal.',null,true,3,1,1009) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f061','geological-assistant','geological-assistant-m3','Twinned crystals','Contact twins meet on a flat composition plane; penetration twins grow through each other; polysynthetic twins repeat on parallel planes; cyclic twins repeat on non-parallel planes (aragonite, chrysoberyl).','Composition plane = the surface where the two individuals are joined. Cyclic aragonite twins look six-sided (pseudo-hexagonal).',null,true,3,1,1010) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f062','geological-assistant','geological-assistant-m3','Twinned crystals','Orthoclase twin laws: Carlsbad - twin axis is the c axis, usually a penetration twin; Baveno - twin plane (021); Manebach - twin plane (001).','Under crossed polars a Carlsbad twin shows as two halves, one bright and one dark. Baveno and Manebach are contact twins and are much rarer.',null,true,3,1,1011) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f063','geological-assistant','geological-assistant-m3','Twinned crystals','Albite law: twin plane (010), repeated polysynthetically; it occurs only in triclinic feldspars (plagioclase, microcline) because (010) is a mirror plane in monoclinic orthoclase.','A plane that is already a symmetry plane cannot act as a twin plane. So striped albite twinning means the feldspar is triclinic.',null,true,3,1,1012) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f064','geological-assistant','geological-assistant-m3','Twinned crystals','Pericline law: the twin axis is the b axis [010]; albite and pericline twins together give the cross-hatched (tartan) pattern of microcline.','The two twin sets cross nearly at right angles. They form when monoclinic potassium feldspar changes to triclinic microcline on slow cooling.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,1013) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f065','geological-assistant','geological-assistant-m3','Twinned crystals','Quartz twins: the Brazil law joins right- and left-handed quartz (optical twin); the Dauphiné law is a 180° rotation about c joining crystals of the same hand (electrical twin).','Either twin spoils quartz for use in oscillators, which need untwinned crystal. Only Brazil twins can be seen with polarised light.',null,true,3,1,1014) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f066','geological-assistant','geological-assistant-m3','Twinned crystals','Japan-law quartz twins are flat contact twins with the two c axes at about 84.5°; Dauphiné twins commonly form when quartz cools through the high-low inversion at 573 °C.','Japan twins look like a flat V or heart. Dauphiné twins are ''transformation twins'' - they appear when the structure changes on cooling.',null,true,2,2,1015) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f067','geological-assistant','geological-assistant-m3','Twinned crystals','Spinel law: the twin plane is the octahedron face {111}; it is seen in spinel, magnetite and diamond (flat triangular ''macles'').','It is the common twin law of cubic minerals that grow as octahedra. Hook: spinel = one-one-one.',null,true,2,2,1016) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f068','geological-assistant','geological-assistant-m3','Twinned crystals','Named twins: swallow-tail - gypsum; cross-shaped (cruciform, at about 90° or 60°) - staurolite; iron cross - pyrite; knee-shaped (elbow) - rutile and cassiterite; interpenetrating cubes - fluorite.','Staurolite takes its name from the Greek for cross. The dark cross of chiastolite (andalusite) is made of inclusions and is not a twin.',null,true,3,1,1017) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f069','geological-assistant','geological-assistant-m3','Twinned crystals','Twins form in three ways: growth twins (Carlsbad), transformation twins (Dauphiné quartz, microcline cross-hatching, leucite) and deformation or glide twins (calcite lamellae, some plagioclase).','Growth = an accident while the crystal grows. Transformation = the structure changes on cooling. Deformation = stress makes layers of the lattice slip.',null,true,2,2,1018) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f070','geological-assistant','geological-assistant-m3','Dispersion','Dispersion is the variation of refractive index with wavelength; in normal dispersion the index is higher for violet (short wavelength) than for red light.','This is why a prism spreads white light into colours. For the same reason standard indices are quoted for one colour: yellow sodium light (589 nm).',null,true,3,1,1019) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f071','geological-assistant','geological-assistant-m3','Dispersion','Strong dispersion gives ''fire'' in gemstones such as diamond; fluorite has very low dispersion and is therefore used in high-quality microscope and camera lenses.','Fire = flashes of rainbow colour as white light is split. A lens needs the opposite: little splitting, so that colours focus together.',null,true,2,2,1020) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f072','geological-assistant','geological-assistant-m3','Dispersion','In biaxial minerals 2V differs for red and violet light (dispersion of the optic axes); it is written r > v or r < v and is seen as colour fringes on the isogyres.','r > v means the optic angle is larger for red light than for violet. Isotropic and uniaxial minerals cannot show it, as they have no 2V.',null,true,3,1,1021) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f073','geological-assistant','geological-assistant-m3','Dispersion','Dispersion types: orthorhombic minerals show rhombic dispersion; monoclinic minerals show inclined, horizontal (parallel) or crossed dispersion; triclinic minerals show asymmetric dispersion.','In monoclinic crystals only b is fixed: inclined if b is the optic normal (Y), horizontal if b is the obtuse bisectrix, crossed if b is the acute bisectrix.',null,true,2,2,1022) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f074','geological-assistant','geological-assistant-m3','Dispersion','Brookite shows crossed axial plane dispersion: its optic plane for red light is at right angles to that for blue light. Sphene shows strong dispersion (r > v) and so incomplete extinction.','When dispersion is very strong, the extinction position differs for each colour. The grain then never goes fully black in white light.',null,true,1,3,1023) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f075','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Light going from a higher-index to a lower-index medium is totally reflected beyond the critical angle C, where sin C = lower index / higher index.','Example: from a mineral of index 2.0 into air, sin C = 1/2, so C = 30°. The Nicol prism uses this effect to throw out the ordinary ray.',null,true,2,2,1024) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f076','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Brewster''s law: light reflected from a transparent surface is fully plane polarised when tan i = n (i = angle of incidence); the reflected and refracted rays are then at 90°.','This is polarisation by reflection. For glass of index 1.5 the polarising angle is about 56° (tan 56.3° = 1.5). It is why polarised sunglasses cut glare from water and roads.',null,false,2,2,1025) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f077','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Polarisation by absorption: tourmaline and Polaroid sheet absorb one of the two rays almost fully and pass the other; modern microscopes use Polaroid filters instead of Nicol prisms.','Tourmaline absorbs the ordinary ray strongly. Three ways to polarise light: reflection (Brewster), double refraction (Nicol prism) and absorption (Polaroid).',null,true,2,2,1026) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f078','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','The quartz wedge is a quartz plate that thickens along its length, giving steadily rising retardation; it is used to find the order of an interference colour and the optic sign.','Push it in over a grain at 45°. If the colours fall to black (compensation), count the red bands passed - that number is the order of the grain''s colour.',null,true,3,1,1027) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f079','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','Under crossed polars a wavelength is cut out when the retardation equals a whole number of that wavelength; the remaining wavelengths give the interference colour.','At 550 nm retardation, green light is removed and we see red-violet. This is the ''sensitive tint'' of the gypsum plate, where a tiny change gives a clear blue or yellow.',null,true,2,2,1028) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f080','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','A biaxial indicatrix has two circular sections of radius beta, and the two optic axes are perpendicular to them; a uniaxial indicatrix has only one circular section, of radius omega.','A circular section means one index for all vibration directions in it. So light travelling at right angles to it (along an optic axis) is not split.',null,true,2,2,1029) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f081','geological-assistant','geological-assistant-m3','Uniaxial and biaxial minerals','Sections cut parallel to the optic axis (uniaxial) or to the optic plane (biaxial) show the maximum interference colour and give a flash figure.','Flash figure = a broad, fuzzy cross that fills the field and leaves it after only a few degrees of rotation. Lowest-colour grains give optic-axis figures instead.',null,true,2,2,1030) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f082','geological-assistant','geological-assistant-m3','Birefringence of minerals and their relation with mineral composition','Normally zoned plagioclase has a calcium-rich core and a sodium-rich rim; under crossed polars the zones show as concentric bands that go extinct at different positions.','Extinction angle changes with composition, so each zone goes dark at its own angle. Calcic plagioclase forms first, at higher temperature. Oscillatory zoning is common in andesites.',null,true,3,1,1031) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f083','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Cordierite looks like quartz or untwinned feldspar (low relief, first-order greys) but is biaxial, shows sector or lamellar twinning, alters to yellowish pinite and has yellow pleochroic haloes.','Pinite = a fine mica-chlorite alteration product. Cordierite gneisses occur in the Kerala Khondalite Belt, so this look-alike matters locally.',null,true,2,2,1032) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3b-f084','geological-assistant','geological-assistant-m3','Optical properties of common rock forming silicate minerals','Leucite has very low refractive index (about 1.51) and very weak birefringence, so it looks almost isotropic; it shows eight-sided outlines and complex lamellar twinning in several directions.','It is cubic when hot and becomes tetragonal on cooling, which creates the fine twins. Nepheline, the other common feldspathoid, is uniaxial negative with no twinning.',null,true,1,3,1033) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f001','geological-assistant','geological-assistant-m3','Classification of mineral deposits','An ore is a natural mineral aggregate from which one or more metals can be extracted at a profit; the worthless minerals mixed with it are called gangue.','Ore is defined by economics, not chemistry. Quartz and calcite are the commonest gangue (waste) minerals.',null,true,3,1,1034) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f002','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Tenor (grade) is the metal content of an ore, stated in percent for base metals and in grams per tonne for precious metals.','Cheap metals need a high tenor: iron ore needs over 50% Fe, copper ore can pay near 1% Cu, gold ore at a few grams per tonne.',null,true,3,1,1035) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f003','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Syngenetic deposits form at the same time as their host rock; epigenetic deposits are introduced into the host rock after it has formed.','Syn = together, epi = after. A coal seam or banded iron formation is syngenetic; a vein cutting across beds is epigenetic.',null,true,3,1,1036) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f004','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Hypogene ores are primary ores deposited by rising (ascending) fluids; supergene ores are secondary ores formed by descending surface waters.','Hypo = from below, super = from above. Supergene processes rework an older hypogene ore near the surface.',null,true,3,1,1037) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f005','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Lindgren''s genetic classification divides hydrothermal deposits by temperature and depth: hypothermal (300-500 °C, deep), mesothermal (200-300 °C) and epithermal (50-200 °C, shallow).','Hypo = deep and hot, meso = middle, epi = shallow and cool. Hook: H-M-E going upward like floors of a building.',null,true,3,1,1038) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f006','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Bateman classified mineral deposits by forming process: magmatic concentration, sublimation, contact metasomatism, hydrothermal processes, sedimentation, evaporation, residual and mechanical concentration, supergene enrichment and metamorphism.','Lindgren sorts by temperature and depth of the fluid. Bateman sorts by the process that made the ore, so it is easier to use in the field.',null,true,3,1,1039) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f007','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Chromite is the classic early magmatic segregation ore: it crystallises early from mafic-ultramafic magma and settles to form layers (stratiform, as in Bushveld) or pods (podiform, in ophiolites).','Chromite is heavy and forms early, so it sinks in the magma chamber. Its hosts are ultramafic-mafic rocks: dunite, peridotite, serpentinite, and pyroxenite-anorthosite layers in Bushveld.',null,true,3,1,1040) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f008','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Nickel-copper sulphide ores such as Sudbury (Canada) form by liquid immiscibility: a dense sulphide liquid separates from mafic magma and sinks, collecting Ni, Cu and platinum-group metals.','Like oil and water, sulphide liquid and silicate magma do not mix. Ni, Cu and PGE are chalcophile (sulphur-loving) and move into the sulphide liquid.',null,true,3,1,1041) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f009','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Pegmatites crystallise from the last water-rich fraction of granitic magma and yield sheet mica, feldspar, beryl, lithium minerals (spodumene, lepidolite), columbite-tantalite and gem tourmaline.','Rare elements do not fit into common minerals, so they stay in the last melt. Water in that melt lets very large crystals grow.',null,true,3,1,1042) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f010','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Skarn (contact metasomatic) deposits form where granitic intrusions react with limestone or dolomite, giving garnet-pyroxene-wollastonite rock with ores of tungsten (scheelite), iron, copper or tin.','Hot fluids from the magma swap material with the carbonate rock (metasomatism = change of composition). Calcium from limestone plus tungsten from granite gives scheelite, CaWO4.',null,true,3,1,1043) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f011','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Porphyry copper deposits are large-tonnage, low-grade ores with disseminated and stockwork Cu (with Mo or Au) in felsic porphyry intrusions above subduction zones.','Grade is often below 1% Cu, but the huge volume makes open-pit mining pay. Alteration is zoned from a potassic core outward to phyllic, argillic and propylitic zones.',null,true,3,1,1044) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f012','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Volcanogenic massive sulphide (VMS) deposits form on the sea floor from hot volcanic springs: Cyprus type is Cu-rich in ophiolitic basalt, Kuroko type is Zn-Pb-Cu in felsic arc volcanics.','Modern black smokers at mid-ocean ridges are VMS deposits forming today. The metal mix follows the volcanic rock below.',null,true,3,1,1045) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f013','geological-assistant','geological-assistant-m3','Classification of mineral deposits','SEDEX (sedimentary exhalative) deposits are layered Zn-Pb-Ag sulphides in shales and carbonates of rift basins, formed where metal-bearing brines vented on the sea floor; Rampura-Agucha is an Indian example.','VMS needs volcanic rocks; SEDEX sits in sediments with little or no volcanic rock. Both are laid down on the sea floor, so the ore is bedded.',null,true,3,1,1046) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f014','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Placers are mechanical concentrations of heavy, hard, chemically stable minerals such as gold, platinum, cassiterite, diamond, ilmenite, rutile, zircon and monazite in stream, beach or hill-slope deposits.','Water or wind carries away light quartz and leaves heavy grains behind. A placer mineral must be heavy, tough and resistant to weathering.',null,true,3,1,1047) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f015','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Residual concentration under hot, wet tropical weathering removes silica and bases and leaves insoluble oxides, forming bauxite, laterite and nickel laterite.','The valuable part is what is left behind after leaching (washing out by rain water). Good drainage and alternate wet and dry seasons help.',null,true,3,1,1048) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f016','geological-assistant','geological-assistant-m3','Classification of mineral deposits','A weathered sulphide ore body shows, from the top down: gossan, leached and oxidised zone, supergene enriched zone near the water table, and unaltered primary sulphide zone.','Rain water with oxygen dissolves metals above the water table. Below it, with no oxygen, the metals are dropped again as rich secondary sulphides.',null,true,3,1,1049) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f017','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Gossan (iron hat) is a rusty, cellular cap of limonite and goethite left after sulphides are oxidised and leached; it guides prospectors to sulphide ore hidden below.','Pyrite rusts to iron hydroxide, which stays at the surface while copper, zinc and sulphur are washed down. The empty box-like holes are called boxwork.',null,true,3,1,1050) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f018','geological-assistant','geological-assistant-m3','Classification of mineral deposits','In copper deposits the oxidised zone carries malachite, azurite, cuprite and native copper, while the supergene enriched zone below the water table carries chalcocite and covellite.','Oxides and carbonates form where oxygen is present. Copper-rich sulphides form below, where copper in solution replaces iron in pyrite and chalcopyrite.',null,true,3,1,1051) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f019','geological-assistant','geological-assistant-m3','Classification of mineral deposits','Banded iron formations are Precambrian chemical sediments of alternating iron oxide and chert bands: Algoma type is small and volcanic-related, Superior type is large and formed on continental shelves.','Most BIF formed about 2.5-1.8 billion years ago, when rising oxygen made dissolved iron in the sea precipitate. In India they are called BHQ, BHJ or BMQ.',null,true,3,1,1052) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f020','geological-assistant','geological-assistant-m3','Classification of mineral deposits','When sea water evaporates, salts precipitate in order of rising solubility: calcite, then gypsum, then halite, and last the potassium-magnesium salts (sylvite, carnallite).','The least soluble salt comes out first. Potash salts are the most soluble, so they form only when the basin is almost dry, which is why they are rare.',null,true,3,1,1053) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f021','geological-assistant','geological-assistant-m3','Controls of mineral localisation','Ore localisation is governed by structural, lithological (physical and chemical nature of the host rock), stratigraphic and igneous (magmatic) controls.','Ore fluids need a path, an opening and a reason to drop their load. Structures give the path, and the host rock gives the trap or the chemical trigger.',null,true,3,1,1054) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f022','geological-assistant','geological-assistant-m3','Controls of mineral localisation','Structural controls such as faults, shear zones, joints, breccias and fold hinges give pathways and open space for ore fluids; saddle reefs at anticlinal crests (Bendigo, Australia) are a classic case.','When beds fold, gaps open at the crest between layers, shaped like a horse saddle. Quartz and gold fill these gaps.',null,true,3,1,1055) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f023','geological-assistant','geological-assistant-m3','Controls of mineral localisation','Lithological control: reactive limestone and dolomite favour replacement ores, brittle rocks fracture and hold veins, and impermeable shale or fault gouge can pond rising fluids so ore collects beneath.','Carbonate rocks neutralise acidic ore fluids, which forces the metals to precipitate. Brittle rocks crack open; soft rocks flow and seal.',null,true,2,2,1056) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f024','geological-assistant','geological-assistant-m3','Controls of mineral localisation','Hydrothermal districts show metal zoning around the heat source; in Cornwall (England) the order outward from the granite is tin, then copper, then lead-zinc.','Each metal drops out at its own temperature as the fluid cools away from the intrusion. Zoning is the order in space; paragenesis is the order in time.',null,true,2,2,1057) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f025','geological-assistant','geological-assistant-m3','Metallogenic epochs and provinces','A metallogenic epoch is a span of geological time in which particular ores formed widely; a metallogenic province is a region marked by a characteristic group of mineral deposits.','Epoch = when, province = where. Example: the Permian is India''s coal epoch; the Dharwar craton is a gold province.',null,true,3,1,1058) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f026','geological-assistant','geological-assistant-m3','Metallogenic epochs and provinces','The Precambrian is India''s most important metallogenic era: it holds the iron, manganese, chromite, gold, copper, lead-zinc, uranium and mica deposits of the Peninsular shield.','Old shield rocks have gone through many cycles of volcanism, sedimentation and metamorphism, each giving a chance to concentrate metals.',null,true,3,1,1059) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f027','geological-assistant','geological-assistant-m3','Metallogenic epochs and provinces','Later Indian metallogenic epochs: Permian (Gondwana) for coal, Tertiary for petroleum and lignite, Tertiary-Quaternary weathering for bauxite and laterite, and Quaternary for beach placers.','Fuels need buried plants or plankton, so they are in younger sedimentary basins. Bauxite and placers are surface products and are the youngest.',null,true,3,1,1060) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f028','geological-assistant','geological-assistant-m3','Metallogenic epochs and provinces','Indian metallogenic provinces include the Dharwar gold province, Singhbhum copper-uranium belt, Aravalli-Delhi lead-zinc-copper belt of Rajasthan, Sausar manganese belt and Jharkhand-Bihar mica belt.','Link each belt to one flagship mine: Kolar and Hutti, Mosabani and Jaduguda, Zawar and Khetri, Balaghat, Koderma.',null,true,3,1,1061) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f029','geological-assistant','geological-assistant-m3','Metallogenic epochs and provinces','Plate setting controls ore type: porphyry copper at subduction zones, podiform chromite and Cyprus-type VMS in ophiolites, tin with collision granites, and diamond in kimberlites of old stable cratons.','Ophiolites are slices of old ocean floor pushed onto land. Diamonds need very thick, cold, old lithosphere, found only under cratons.',null,true,3,1,1062) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f030','geological-assistant','geological-assistant-m3','Precious metals','Kolar Gold Fields (Karnataka) worked gold-quartz lodes such as the Champion reef in hornblende schists of the Kolar schist belt to over 3 km depth; mining closed in 2001.','It was one of the deepest mines in the world. The lodes follow shear zones in an Archaean greenstone belt of the Dharwar craton.',null,true,3,1,1063) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f031','geological-assistant','geological-assistant-m3','Precious metals','Hutti mine (Hutti-Maski schist belt, Raichur, Karnataka) is India''s main working gold mine; Karnataka gave about 99% of primary gold in 2021-22 (IBM).','After Kolar closed in 2001, Hutti became the chief producer. Figure from Indian Minerals Yearbook 2022 (IBM) for 2021-22; the balance came from Jharkhand. Production data change yearly.',null,true,3,1,1064) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f032','geological-assistant','geological-assistant-m3','Precious metals','In India silver is won mainly as a by-product of Rajasthan lead-zinc ores, and platinum-group elements occur with chromite in the Baula-Nuasahi ultramafic complex of Odisha.','Galena often carries silver (argentiferous galena). Platinum metals worldwide follow mafic-ultramafic rocks, as in the Merensky Reef of Bushveld.',null,true,2,2,1065) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f033','geological-assistant','geological-assistant-m3','Precious metals','In Kerala, gold occurs in the Nilambur valley (Malappuram) as placer gold in gravels of the Chaliyar river system and as primary gold-quartz veins of the Wayanad-Nilambur belt.','Rivers wash gold out of the veins in the hills and drop the heavy grains in gravel beds. Local people have panned it for generations.',null,true,3,1,1066) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f034','geological-assistant','geological-assistant-m3','Non-ferrous metals','Copper ore minerals: chalcopyrite CuFeS2 (the chief ore), bornite Cu5FeS4, chalcocite Cu2S, covellite CuS, cuprite Cu2O, malachite and azurite (green and blue copper carbonates).','Chalcopyrite has about 34.6% Cu and is brass yellow. Bornite is called peacock ore for its purple-blue tarnish.',null,true,3,1,1067) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f035','geological-assistant','geological-assistant-m3','Non-ferrous metals','Lead ore minerals are galena PbS, cerussite PbCO3 and anglesite PbSO4; zinc ore minerals are sphalerite ZnS, smithsonite ZnCO3 and zincite ZnO.','Galena and sphalerite almost always occur together, so we speak of lead-zinc deposits. The carbonates and sulphate form in the oxidised zone.',null,true,3,1,1068) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f036','geological-assistant','geological-assistant-m3','Non-ferrous metals','Bauxite (gibbsite, boehmite, diaspore) is a residual aluminium ore; Odisha holds about 41% of India''s resources (IBM, IMY 2022, as on 1.4.2020), mainly East Coast bauxite capping khondalite hills such as Panchpatmali.','Gibbsite is Al(OH)3; boehmite and diaspore are AlO(OH). In central and western India bauxite caps Deccan basalt instead (Amarkantak, Lohardaga, Gujarat).',null,true,3,1,1069) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f037','geological-assistant','geological-assistant-m3','Non-ferrous metals','The Khetri copper belt (Jhunjhunu district, Rajasthan) has chalcopyrite-pyrrhotite ore in metasedimentary rocks of the Delhi Supergroup; mines include Khetri and Kolihan.','Hook: Khetri = Rajasthan copper, in the Delhi fold belt. Zawar, also in Rajasthan, is lead-zinc and sits in the older Aravalli rocks.','CUET PG 2026',true,3,1,1070) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f038','geological-assistant','geological-assistant-m3','Non-ferrous metals','Malanjkhand (Balaghat district, Madhya Pradesh) is India''s largest open-pit copper mine; chalcopyrite occurs in a quartz reef within Proterozoic granitoid and is often compared with porphyry copper.','Khetri ore is in metasediments, Malanjkhand ore is in granite. This contrast is a favourite exam comparison.','GATE Geology & Geophysics (GG) 2022',true,3,1,1071) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f039','geological-assistant','geological-assistant-m3','Non-ferrous metals','The Singhbhum copper belt (Mosabani, Rakha, Surda; Jharkhand) lies along the arc-shaped Singhbhum Shear Zone, which also hosts the Jaduguda uranium deposit.','A shear zone is a belt of crushed, sheared rock. It acted as the channel for ore fluids, a clear case of structural control.',null,true,3,1,1072) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f040','geological-assistant','geological-assistant-m3','Non-ferrous metals','In Rajasthan, Zawar (Udaipur) has lead-zinc ore in Aravalli dolomite, while Rampura-Agucha (Bhilwara) is a world-class SEDEX zinc-lead deposit in graphite-mica-sillimanite schist.','Zawar is also famous for ancient zinc smelting. Rampura-Agucha, Zawar and Rajpura-Dariba are all worked by Hindustan Zinc Ltd.','CUET PG 2026',true,3,1,1073) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f041','geological-assistant','geological-assistant-m3','Iron and ferro-alloy metals','Iron ore minerals by iron content: magnetite Fe3O4 (72.4% Fe), hematite Fe2O3 (about 70%), goethite and limonite (hydrated oxides, about 60%), siderite FeCO3 (48.2%).','Magnetite is black and magnetic with a black streak. Hematite has a cherry-red streak and is India''s main ore.',null,true,3,1,1074) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f042','geological-assistant','geological-assistant-m3','Iron and ferro-alloy metals','Most Indian iron ore is hematite formed by natural enrichment of Precambrian banded iron formations (BHQ, BHJ), where silica was leached out and iron stayed.','BHQ = banded hematite quartzite, BHJ = banded hematite jasper. Remove the silica bands and what is left is rich hematite.',null,true,3,1,1075) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f043','geological-assistant','geological-assistant-m3','Iron and ferro-alloy metals','Bailadila (Dantewada, Bastar region, Chhattisgarh) has very high-grade hematite worked by NMDC; Noamundi, Gua and Kiriburu lie in the horse-shoe shaped Iron Ore Group syncline of Jharkhand-Odisha.','Bailadila means hump of an ox, from the shape of the range. Noamundi feeds Tata Steel at Jamshedpur.','CUET PG 2026',true,3,1,1076) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f044','geological-assistant','geological-assistant-m3','Iron and ferro-alloy metals','Kudremukh (Chikkamagaluru district, Karnataka) is a large low-grade magnetite quartzite deposit; mining there stopped at the end of 2005 to protect the Western Ghats forests.','Kudremukh means horse face. Unlike most Indian mines its ore is magnetite, not hematite, so it had to be concentrated and made into pellets.',null,true,2,2,1077) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f045','geological-assistant','geological-assistant-m3','Iron and ferro-alloy metals','Kerala''s iron ore is low-grade banded magnetite quartzite in Kozhikode district (Cheruppa, Nanminda, Naduvallur, Eleyettimala) and in Malappuram district; it has not been mined commercially.','The bands lie within the Precambrian gneisses and charnockites. Same ore type as Kudremukh: magnetite plus quartz.',null,true,3,1,1078) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f046','geological-assistant','geological-assistant-m3','Iron and ferro-alloy metals','Manganese ore minerals are pyrolusite MnO2, psilomelane, braunite and manganite; rhodochrosite MnCO3 and rhodonite MnSiO3 are the pink manganese minerals.','Pyrolusite is soft, black and soils the fingers. Manganese is used mostly in steel making, to remove sulphur and oxygen.',null,true,3,1,1079) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f047','geological-assistant','geological-assistant-m3','Iron and ferro-alloy metals','Gondite is a spessartite garnet-quartz rock with the manganese ores of the Sausar Group (Balaghat, Nagpur, Bhandara); kodurite is the manganese-bearing rock of the Eastern Ghats of Andhra Pradesh.','Both names were given by Fermor. Gondite is named after the Gond people of central India, kodurite after Kodur village.',null,true,3,1,1080) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f048','geological-assistant','geological-assistant-m3','Iron and ferro-alloy metals','Chromite FeCr2O4 is the only ore of chromium; the Sukinda valley (Jajpur) and Baula-Nuasahi in Odisha hold about 96% of India''s chromite resources (IBM, Indian Minerals Yearbook 2022).','The chromite lies in ultramafic rocks. Nickel-bearing laterite over the same Sukinda rocks holds most of India''s nickel resources too.','GATE Geology & Geophysics (GG) 2022',true,3,1,1081) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f049','geological-assistant','geological-assistant-m3','Mineral fuels','Coal rank rises from peat to lignite, sub-bituminous, bituminous and anthracite; fixed carbon and heating value increase while moisture and volatile matter decrease.','Burial heat and pressure drive off water and gases, leaving more carbon. Rank is measured by vitrinite reflectance (shine of the main coal component).',null,true,3,1,1082) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f050','geological-assistant','geological-assistant-m3','Mineral fuels','Almost all of India''s coal is Gondwana coal of Permian age, in the Barakar and Raniganj Formations (Damuda Group) of the Damodar, Son-Mahanadi and Godavari valley basins.','The Barakar Formation has the most and the best seams. Gondwana coal is bituminous, high in ash and low in sulphur.',null,true,3,1,1083) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f051','geological-assistant','geological-assistant-m3','Mineral fuels','Jharia (Dhanbad, Jharkhand) is India''s chief source of prime coking coal; Raniganj (West Bengal) is the oldest coalfield, where mining began in 1774.','Coking coal is needed to make steel. Other big Gondwana fields are Bokaro, Talcher, Korba, Singrauli and Singareni.',null,true,3,1,1084) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f052','geological-assistant','geological-assistant-m3','Mineral fuels','Tertiary coals occur in Assam (Makum), Meghalaya, Nagaland and Arunachal Pradesh; they are of Eocene-Oligocene age and high in sulphur.','They formed in swamps near the sea, and sea water supplies sulphur. Gondwana coal formed in river basins, so it has little sulphur.',null,true,3,1,1085) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f053','geological-assistant','geological-assistant-m3','Mineral fuels','Neyveli (Cuddalore district, Tamil Nadu) is India''s largest lignite field, of Miocene age; a confined aquifer under pressure below the seam must be pumped continuously for safe mining.','If the artesian pressure is not lowered, water can burst through the mine floor. Other lignite fields: Kutch, and Barmer and Bikaner in Rajasthan.',null,true,3,1,1086) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f054','geological-assistant','geological-assistant-m3','Mineral fuels','Digboi in Upper Assam is India''s oldest oil field (oil struck in 1889, refinery from 1901); Assam oil comes from Tertiary sandstones such as the Tipam and Barail.','Other Upper Assam fields are Naharkatiya, Moran and Rudrasagar. Hook: the name is said to come from the cry: dig, boy, dig.',null,true,3,1,1087) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f055','geological-assistant','geological-assistant-m3','Mineral fuels','Mumbai High, an offshore field found in 1974, produces from Miocene limestone; Cambay basin fields (Ankleshwar) produce from Eocene sandstone; the Krishna-Godavari basin has the Ravva oil field and deep-water KG-D6 gas.','Every oil field needs a source rock, a porous reservoir rock, a tight cap rock and a trap. Mumbai High is India''s largest oil field.',null,true,3,1,1088) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f056','geological-assistant','geological-assistant-m3','Mineral fuels','Uranium deposits of India: Jaduguda (Singhbhum Shear Zone, Jharkhand, the first mine), Tummalapalle (in Vempalle dolostone of the Cuddapah basin, Andhra Pradesh) and Domiasiat (in Cretaceous Mahadek sandstone, Meghalaya).','Three different host rocks: sheared schist, dolostone and sandstone. The main uranium mineral is uraninite (pitchblende), UO2.',null,true,3,1,1089) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f057','geological-assistant','geological-assistant-m3','Ceramic minerals','China clay (kaolin) is mainly kaolinite, Al2Si2O5(OH)4, formed by weathering or hydrothermal alteration of feldspar; a ceramic body needs clay for plasticity, feldspar as flux and quartz as filler.','Flux means it melts first and glues the body together. Good china clay is white because it has almost no iron.',null,true,3,1,1090) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f058','geological-assistant','geological-assistant-m3','Ceramic minerals','Ball clay is a very plastic sedimentary clay, fire clay is a refractory clay often found under coal seams, and bentonite is montmorillonite clay formed from altered volcanic ash.','Bentonite swells in water and is used in drilling mud. In India it comes mainly from Barmer (Rajasthan) and Kutch (Gujarat).',null,true,2,2,1091) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f059','geological-assistant','geological-assistant-m3','Ceramic minerals','Kerala''s best-known china clay deposit is at Kundara (Kollam district); the state holds about 23% of India''s china clay resources (IBM, IMY 2022; inventory as on 1.4.2015).','The clay occurs in the Tertiary Warkalli beds and as residual clay over weathered gneiss. Thonnakkal near Thiruvananthapuram is another centre.',null,false,3,1,1092) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f060','geological-assistant','geological-assistant-m3','Structural and building materials','Portland cement is made from limestone (low in magnesia) and clay burnt to clinker; about 3-5% gypsum (CaSO4.2H2O) is added during grinding to slow down setting.','Without gypsum, cement would set almost at once (flash set). Heated gypsum loses water and becomes plaster of Paris.',null,true,3,1,1093) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f061','geological-assistant','geological-assistant-m3','Structural and building materials','Famous Indian building stones: Makrana marble (Rajasthan) of the Taj Mahal, Vindhyan red sandstone of Red Fort, Kota stone (Vindhyan limestone) and Cuddapah slabs; granite, charnockite and basalt give road metal.','A good building stone is strong, dense, low in porosity and resists weathering. In Kerala, charnockite and gneiss are the main crushed stone.',null,true,2,2,1094) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f062','geological-assistant','geological-assistant-m3','Structural and building materials','Laterite was named by Francis Buchanan in 1807 at Angadipuram (Malappuram, Kerala), where the soft rock is cut into bricks that harden on exposure to air.','Later is Latin for brick. Laterite caps much of the Kerala midlands and is the traditional building stone of Malabar.',null,true,3,1,1095) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f063','geological-assistant','geological-assistant-m3','Metallurgical and refractory materials','Refractories resist very high temperatures: acid types are silica (quartzite) and fire clay, basic types are magnesite and dolomite, and neutral types are chromite and graphite.','The furnace lining must match the slag. Basic slag eats an acid lining, so basic steel furnaces are lined with magnesite or dolomite.',null,true,3,1,1096) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f064','geological-assistant','geological-assistant-m3','Metallurgical and refractory materials','Limestone and dolomite are the fluxes of the iron blast furnace, and fluorspar (CaF2) is a flux in steel making; India''s main fluorite deposit is at Ambadongar, Gujarat, in carbonatite.','A flux joins with silica gangue to make a liquid slag that floats and is tapped off. Carbonatite is a rare igneous rock made of carbonate minerals.','CUET PG 2026',true,2,2,1097) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f065','geological-assistant','geological-assistant-m3','Metallurgical and refractory materials','Magnesite (MgCO3) at Salem, Tamil Nadu (Chalk Hills) occurs as white veins in dunite and peridotite, formed when CO2-bearing waters altered the magnesium-rich ultramafic rock.','The white veins on the hills look like chalk, hence the name. Magnesite in Uttarakhand (Almora, Pithoragarh) instead replaces dolomite.',null,true,3,1,1098) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f066','geological-assistant','geological-assistant-m3','Metallurgical and refractory materials','Kyanite and sillimanite (both Al2SiO5) are high-alumina refractories that turn to mullite on heating; Lapsa Buru (Singhbhum, Jharkhand) is the classic kyanite deposit and Sonapahar (Meghalaya) the classic sillimanite deposit.','Mullite stays strong at very high heat, so these minerals go into furnace bricks and spark plugs. Both are metamorphic minerals.',null,true,2,2,1099) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f067','geological-assistant','geological-assistant-m3','Metallurgical and refractory materials','Graphite is metamorphosed carbon, found as flakes in khondalite of the Eastern Ghats (Odisha) and of Kerala (Thiruvananthapuram, Kollam, Kottayam, Idukki, Ernakulam); it is used in crucibles and electrodes.','Khondalite is garnet-sillimanite-graphite gneiss. Graphite does not melt and conducts heat and electricity, so it suits crucibles.',null,true,2,2,1100) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f068','geological-assistant','geological-assistant-m3','Fertilizer minerals','Fertilizer elements are N, P and K: phosphorus comes from rock phosphate and apatite, potassium from potash salts (sylvite KCl, carnallite, polyhalite), and nitrogen mostly from the air.','Rock phosphate is treated with sulphuric acid to make superphosphate. Gypsum and pyrite (for sulphur) are also counted as fertilizer minerals.',null,true,3,1,1101) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f069','geological-assistant','geological-assistant-m3','Fertilizer minerals','Jhamarkotra (Udaipur, Rajasthan) is India''s largest rock phosphate deposit: stromatolitic phosphorite in dolomite of the Proterozoic Aravalli Supergroup.','Stromatolites are layered mounds built by algae-like microbes, which trapped the phosphate. The Mussoorie phosphorite is younger (Tal Formation).',null,true,3,1,1102) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f070','geological-assistant','geological-assistant-m3','Fertilizer minerals','India has no working potash mine and imports its potash; potash salts (polyhalite, sylvite) are known in the buried evaporites of the Nagaur-Ganganagar basin, Rajasthan.','Potash salts form only in the last stage of sea water evaporation and dissolve easily, so they survive only deep underground. Status as known in 2025.',null,false,2,2,1103) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f071','geological-assistant','geological-assistant-m3','Abrasive minerals','Natural abrasives in order of hardness: diamond (10), corundum (9), emery (corundum mixed with magnetite) and garnet (6.5-7.5); softer ones include quartz sand, pumice and diatomite.','An abrasive must be harder than the thing it grinds. Garnet is used in sandpaper and in water-jet cutting.',null,true,3,1,1104) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f072','geological-assistant','geological-assistant-m3','Abrasive minerals','In India, abrasive garnet is recovered from beach sands of Tamil Nadu, Kerala and Odisha, and corundum occurs with sillimanite at Pipra (Madhya Pradesh) and Sonapahar (Meghalaya).','Garnet is a heavy mineral, so it collects in the same placers as ilmenite. Corundum and sillimanite are both alumina-rich metamorphic minerals.',null,true,2,2,1105) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f073','geological-assistant','geological-assistant-m3','Gemstones','Ruby (red, coloured by chromium) and sapphire (blue, by iron and titanium) are gem corundum, Al2O3; emerald (green) and aquamarine (blue) are gem beryl, Be3Al2Si6O18.','Same mineral, different trace element, different gem. India''s famous sapphire comes from Paddar in Kashmir and emerald from the Ajmer-Udaipur belt of Rajasthan.',null,true,3,1,1106) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f074','geological-assistant','geological-assistant-m3','Gemstones','Chrysoberyl (BeAl2O4, hardness 8.5) has two gem varieties, alexandrite (colour-changing) and cat''s eye; in Kerala it occurs in pegmatites and gem gravels of Thiruvananthapuram and Kollam districts.','Alexandrite looks green in daylight and red in lamp light. The pegmatites cut the khondalite belt of south Kerala.',null,true,3,1,1107) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f075','geological-assistant','geological-assistant-m3','Gemstones','Diamond comes from kimberlite and lamproite pipes and their placers; in India the Majhgawan pipe at Panna (Madhya Pradesh) is the site of NMDC''s diamond mine, and Wajrakarur (Anantapur, Andhra Pradesh) has kimberlite pipes.','Kimberlite brings diamonds up fast from over 150 km depth. The old Golconda diamonds came from Krishna river gravels.','GATE Geology & Geophysics (GG) 2022',true,3,1,1108) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f076','geological-assistant','geological-assistant-m3','Mineral deposits of India','The Chavara beach placer (Neendakara to Kayamkulam, Kollam district, Kerala) is rich in ilmenite, rutile, zircon, monazite, sillimanite and garnet, and is mined by IREL and KMML.','Formulae: ilmenite FeTiO3, rutile TiO2, zircon ZrSiO4, sillimanite Al2SiO5. Chavara ilmenite is prized for its high TiO2 (about 60%).','UPSC Civil Services Prelims 2006',true,3,1,1109) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f077','geological-assistant','geological-assistant-m3','Mineral deposits of India','Kerala''s beach heavy minerals come from weathered khondalite, charnockite, gneiss and pegmatite of the hinterland, carried by rivers and sorted by waves; monazite in them is India''s thorium source.','Waves and longshore currents wash away light quartz and leave heavy black sand. Monazite is a rare-earth and thorium phosphate, so it is a nuclear mineral.',null,true,3,1,1110) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f078','geological-assistant','geological-assistant-m3','Mineral deposits of India','Other Kerala minerals: glass-grade silica sand in the Cherthala-Alappuzha belt, bauxite at Nileshwaram (Kasaragod), lime shell in Vembanad Lake, and lignite at Madayi (Kannur).','Kerala has no coal, oil or big metal mines. Its strength is beach sand, china clay and silica sand.',null,true,3,1,1111) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f079','geological-assistant','geological-assistant-m3','Mineral deposits of India','Muscovite mica comes from pegmatites cutting mica schist; the Koderma-Giridih-Hazaribagh belt (Jharkhand-Bihar) yields ruby mica, with other belts at Nellore (Andhra Pradesh) and Bhilwara (Rajasthan).','Koderma is called the mica capital of India. Sheet mica splits thin and does not conduct electricity, so it is an insulator.',null,true,3,1,1112) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3c-f080','geological-assistant','geological-assistant-m3','Mineral deposits of India','Mangampet (Kadapa region, Andhra Pradesh) has one of the world''s largest single barytes (BaSO4) deposits, bedded in Pullampet shales of the Cuddapah Supergroup; barytes is used as oil-well drilling mud.','Barytes is very heavy (specific gravity about 4.5). Heavy mud holds down gas and oil pressure in a well.','GATE Geology & Geophysics (GG) 2022',true,3,1,1113) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f001','geological-assistant','geological-assistant-m4','Forms of igneous rocks','A sill is a sheet-like (tabular) concordant intrusion: it lies parallel to the bedding or foliation of the country rock.','Concordant means it follows the layers. Memory hook: a window sill lies flat, like the beds.',null,true,3,1,1114) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f002','geological-assistant','geological-assistant-m4','Forms of igneous rocks','A dyke is a tabular discordant intrusion: it cuts across the bedding or foliation of the country rock.','Discordant means it cuts the layers. Dykes fill cracks, so they are usually steep. Dolerite is the commonest dyke rock.',null,true,3,1,1115) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f003','geological-assistant','geological-assistant-m4','Forms of igneous rocks','A laccolith is a concordant intrusion with a flat floor and a domed roof, usually built by viscous acid (silica-rich) magma.','Thick, sticky magma cannot spread far sideways. It piles up and lifts the roof beds, like a mushroom cap.','Kerala PSC Junior Petrological Analyst (KMML) 2026',true,3,1,1116) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f004','geological-assistant','geological-assistant-m4','Forms of igneous rocks','A lopolith is a very large, saucer-shaped (basin-like) concordant intrusion, usually of mafic rock; the Bushveld Complex is the classic example.','Lopo = basin. The centre sags under the weight of heavy mafic magma. Laccolith bulges up; lopolith sags down.',null,true,3,1,1117) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f005','geological-assistant','geological-assistant-m4','Forms of igneous rocks','A phacolith is a lens-shaped concordant intrusion found at the crests of anticlines and the troughs of synclines in folded strata.','Folding opens low-pressure gaps at fold hinges, and magma moves into them. Phaco = lens.',null,true,3,1,1118) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f006','geological-assistant','geological-assistant-m4','Forms of igneous rocks','A batholith is the largest discordant pluton, mostly granite or granodiorite, with exposed area above 100 square km and no visible floor; a smaller one is a stock.','Batho = deep. The 100 square km limit separates batholith from stock. A stock with a round outline is called a boss.',null,true,3,1,1119) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f007','geological-assistant','geological-assistant-m4','Forms of igneous rocks','Ring dykes are vertical or steeply outward-dipping and form by cauldron subsidence; cone sheets dip inward to a common centre and form by upward magma pressure.','Ring dyke: a roof block sinks and magma rises around it. Cone sheet: magma pushes the roof up and opens inward-dipping cracks. Both are classic on Mull, Scotland.',null,true,2,2,1120) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f008','geological-assistant','geological-assistant-m4','Textures of igneous rocks','By crystallinity, igneous rocks are holocrystalline (all crystals), holohyaline (all glass, like obsidian) or hypocrystalline (crystals plus glass).','Holo = whole, hyaline = glassy. Glass forms when lava cools too fast for crystals to grow.','Goa PSC Assistant Professor Geology 2021',true,2,2,1121) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f009','geological-assistant','geological-assistant-m4','Textures of igneous rocks','Slow cooling at depth gives coarse (phaneritic) grains because few nuclei form and grow large; fast cooling of lava gives fine (aphanitic) grains or glass.','Nuclei are the tiny starting points of crystals. Slow cooling = few nuclei, big crystals. Fast cooling = many nuclei, tiny crystals.','Kerala PSC HSST Geology 2026',true,3,1,1122) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f010','geological-assistant','geological-assistant-m4','Textures of igneous rocks','Porphyritic texture has large crystals (phenocrysts) set in a finer groundmass, usually recording two stages of cooling; with a glassy groundmass it is called vitrophyric.','The big crystals grew slowly at depth. Then the magma rose and the rest cooled quickly around them.',null,true,3,1,1123) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f011','geological-assistant','geological-assistant-m4','Textures of igneous rocks','In ophitic texture, plagioclase laths are wholly enclosed in large augite crystals; it is the typical texture of dolerite.','Plagioclase started growing first as many small laths. Augite grew later as a few big crystals that wrapped around them.','Goa PSC Assistant Geologist 2021; Goa PSC Assistant Professor Geology 2021',true,3,1,1124) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f012','geological-assistant','geological-assistant-m4','Textures of igneous rocks','In poikilitic texture, a large host crystal (oikocryst) encloses many small, randomly oriented crystals (chadacrysts) of other minerals.','Oikos = house: the big crystal houses the small ones. Ophitic texture is a special kind of poikilitic texture.',null,true,2,2,1125) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f013','geological-assistant','geological-assistant-m4','Textures of igneous rocks','Graphic texture is a regular intergrowth of quartz in alkali feldspar that looks like ancient wedge-shaped writing; it is typical of granite pegmatites.','Quartz and K-feldspar crystallise at the same time from the last melt. The microscopic version is called granophyric.',null,true,3,1,1126) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f014','geological-assistant','geological-assistant-m4','Textures of igneous rocks','Perthite is K-feldspar hosting exsolved lamellae of albite; antiperthite is the reverse, a plagioclase host with K-feldspar blebs.','Hot Na- and K-feldspar mix into one crystal. On slow cooling they unmix (exsolution), like oil separating from water.','Goa PSC Assistant Professor Geology 2021',true,3,1,1127) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f015','geological-assistant','geological-assistant-m4','Textures of igneous rocks','Myrmekite is an intergrowth of worm-like (vermicular) quartz in sodic plagioclase, usually found next to K-feldspar in granitic rocks.','Myrmex = ant; the quartz looks like ant tunnels. Do not confuse with graphic texture, where quartz sits in K-feldspar.','Kerala PSC Assistant Geologist (Mining & Geology) 2025',true,3,1,1128) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f016','geological-assistant','geological-assistant-m4','Textures of igneous rocks','Rapakivi texture shows large rounded K-feldspar (orthoclase) crystals mantled by a rim of plagioclase (oligoclase); it is named from Proterozoic granites of Finland.','Rapakivi is Finnish for crumbly stone. Hook: pink egg with a white shell. These granites are anorogenic (A-type).','UPSC Combined Geo-Scientist Mains 2020 Geology Paper II',true,3,1,1129) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f017','geological-assistant','geological-assistant-m4','Textures of igneous rocks','Spinifex texture consists of long skeletal blades of olivine (or pyroxene) formed by rapid cooling of ultramafic lava; it is diagnostic of komatiite.','Named after spiky Australian spinifex grass. Komatiite is a magnesium-rich lava (over 18% MgO), almost all of Archaean age.',null,true,3,1,1130) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f018','geological-assistant','geological-assistant-m4','Textures of igneous rocks','In basaltic rocks, intersertal texture has glass filling the gaps between plagioclase laths, while intergranular texture has small pyroxene grains in those gaps.','Same framework of laths, different filling. Glass filling = cooled faster. Granules filling = had time to crystallise.','Kerala PSC Assistant Geologist (Mining & Geology) 2025',true,2,2,1131) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f019','geological-assistant','geological-assistant-m4','Textures of igneous rocks','A reaction rim (corona) is a shell of a new mineral around an earlier crystal that reacted with the melt, such as orthopyroxene around olivine.','Early olivine is no longer stable as the melt gets richer in silica. It reacts at its edge to make pyroxene, as Bowen''s series predicts.',null,true,2,2,1132) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f020','geological-assistant','geological-assistant-m4','Structures of igneous rocks','Vesicular structure is formed by escaping gas bubbles; scoria is dark vesicular basaltic rock, and pumice is light frothy silicic glass that can float on water.','Gas comes out of lava when pressure drops, like opening a soda bottle. Pumice has so many holes that it is lighter than water.','Goa PSC Assistant Geologist 2021',true,3,1,1133) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f021','geological-assistant','geological-assistant-m4','Structures of igneous rocks','When vesicles are later filled by secondary minerals such as zeolites, calcite or agate, the fillings are amygdales and the structure is amygdaloidal.','Amygdale = almond-shaped. Deccan Trap basalts are famous for cavities filled with zeolites.',null,true,3,1,1134) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f022','geological-assistant','geological-assistant-m4','Structures of igneous rocks','Pillow structure forms when basaltic lava erupts under water; each pillow has a convex top and a glassy chilled skin.','Water chills the lava into bag-like lobes. Pillows prove underwater eruption and show which way was up. Sodium-rich pillow basalt with albite is called spilite.',null,true,3,1,1135) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f023','geological-assistant','geological-assistant-m4','Structures of igneous rocks','Columnar joints are polygonal, commonly six-sided columns formed by contraction of cooling lava or shallow intrusions; the columns grow at right angles to the cooling surface.','Rock shrinks as it cools and cracks like drying mud. Indian example: St. Mary''s Islands off Udupi, Karnataka; also seen in Deccan basalts.',null,true,3,1,1136) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f024','geological-assistant','geological-assistant-m4','Structures of igneous rocks','Pahoehoe is basaltic lava with a smooth, ropy surface; aa lava has a rough, jagged, clinkery surface and is more viscous.','Both are Hawaiian words. Pahoehoe is hot and runny, so its skin wrinkles like rope. Aa is cooler and stiffer, so its crust breaks into rubble.','Kerala PSC Junior Petrological Analyst (KMML) 2026',true,3,1,1137) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f025','geological-assistant','geological-assistant-m4','Structures of igneous rocks','Flow structure (flow banding) is a streaky layering produced by movement of viscous lava; it is best developed in rhyolite and obsidian.','Sticky lava smears out bands of different colour or crystal content as it creeps. The name rhyolite itself comes from the Greek for flow.',null,true,2,2,1138) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f026','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Bowen''s discontinuous reaction series runs olivine, then pyroxene, then amphibole, then biotite, with falling temperature.','Each mineral reacts with the melt to form the next one. Hook: O-P-A-B. Silicate structure also grows: islands, chains, double chains, sheets.',null,true,3,1,1139) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f027','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Bowen''s continuous reaction series is the plagioclase feldspars, changing smoothly from calcium-rich (anorthite) at high temperature to sodium-rich (albite) at low temperature.','Continuous = same mineral structure, only the composition shifts. That is why basalt has calcic plagioclase and granite has sodic plagioclase.',null,true,3,1,1140) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f028','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','In Bowen''s reaction series, K-feldspar, muscovite and quartz crystallise last, at the lowest temperatures; quartz is the final mineral.','Goldich''s weathering series follows the same order as Bowen''s: first-formed olivine weathers fastest, last-formed quartz resists longest. High-temperature minerals are least stable at the surface.',null,true,3,1,1141) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f029','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Fractional crystallisation, in which early crystals separate from the melt (for example by gravity settling), is the main process of magmatic differentiation.','Removing early Mg-Fe minerals leaves the remaining melt richer in silica and alkalis. Heavy chromite or olivine sinking to the floor makes layered rocks.','Kerala PSC Junior Petrological Analyst (KMML) 2026',true,3,1,1142) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f030','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Assimilation is the incorporation and digestion of country rock by magma, which changes the magma composition; partly digested xenoliths are its field evidence.','Xenolith = foreign rock piece inside an igneous rock. Melting wall rock uses up heat, so assimilation usually goes with crystallisation.',null,true,2,2,1143) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f031','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Magma viscosity increases with silica content and decreases with higher temperature and dissolved water; rhyolitic magma is far more viscous than basaltic magma.','Silica tetrahedra link into long chains and networks that resist flow. So basalt makes quiet flows and rhyolite makes domes and explosions.',null,true,3,1,1144) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f032','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','By silica content, igneous rocks are ultrabasic (below 45% SiO2), basic (45-52%), intermediate, and acid (above 66% in the classical scheme; 63% in the TAS diagram).','Examples in order: peridotite, basalt, andesite, granite. Acid here means silica-rich, not low pH.',null,true,3,1,1145) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f033','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Colour index is the volume percentage of dark (mafic) minerals in a rock; leucocratic rocks are light with a low index and melanocratic rocks are dark with a high index.','Leuco = white, melano = black, meso = in between. Granite is leucocratic; gabbro is mesocratic to melanocratic.',null,true,2,2,1146) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f034','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','The IUGS (Streckeisen) QAPF classification uses modal quartz (Q), alkali feldspar (A), plagioclase (P) and feldspathoids (F), and applies when mafic minerals are below 90%.','Modal = actually measured minerals. It is a double triangle because quartz and feldspathoids never occur together. Above 90% mafics, ultramafic diagrams are used.',null,true,3,1,1147) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f035','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','The TAS diagram plots total alkalis (Na2O + K2O) against SiO2 and is used to name volcanic rocks whose minerals are too fine or glassy to count.','TAS = Total Alkali-Silica. When you cannot see the minerals, you use chemistry instead of the QAPF mode.',null,true,3,1,1148) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f036','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','In Shand''s silica saturation scheme, oversaturated rocks have free quartz and undersaturated rocks have feldspathoids or Mg-olivine; quartz never coexists with nepheline or leucite.','Feldspathoids are silica-poor stand-ins for feldspar. If spare silica were present, it would react with them to make feldspar instead.',null,true,3,1,1149) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f037','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Peraluminous rocks have molar Al2O3 greater than CaO + Na2O + K2O (muscovite, garnet, cordierite); peralkaline rocks have Al2O3 less than Na2O + K2O (aegirine, riebeckite).','Extra alumina makes Al-rich minerals. Extra alkalis make sodium-rich pyroxene and amphibole. Metaluminous rocks lie in between (hornblende).',null,true,2,2,1150) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f038','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','The CIPW norm is a set of ideal anhydrous minerals calculated from a rock''s chemical analysis; the mode is the mineral content actually measured in the rock.','Named after Cross, Iddings, Pirsson and Washington. Normative quartz means silica-oversaturated; normative nepheline means undersaturated.',null,true,3,1,1151) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f039','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Diopside-anorthite at 1 atmosphere is a simple binary eutectic with no solid solution; the eutectic lies at about 1274 °C and 42% anorthite.','Eutectic = the lowest-melting mixture, where both minerals crystallise together. It is the simple model for basalt (pyroxene + plagioclase).',null,true,2,2,1152) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f040','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Albite-anorthite (plagioclase) shows complete solid solution with a liquidus-solidus loop between 1118 °C (albite) and 1553 °C (anorthite), and has no eutectic.','Crystals are always richer in anorthite than the melt they grow from. If they cannot re-react, you get zoned plagioclase: calcic core, sodic rim.','UPSC Combined Geo-Scientist Mains 2020 Geology Paper II',true,3,1,1153) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f041','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','In the forsterite-silica system, enstatite melts incongruently to forsterite plus liquid at a peritectic point (about 1557 °C at 1 atmosphere).','Incongruent = the solid breaks into a different solid plus melt. On cooling, olivine reacts with melt to make pyroxene, so Mg-olivine and quartz do not occur together.','UPSC Combined Geo-Scientist Mains 2020 Geology Paper II; Kerala PSC Junior Petrological Analyst (KMML) 2026',true,3,1,1154) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f042','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Basaltic magma forms by partial melting of mantle peridotite: by decompression at mid-ocean ridges and hotspots, and by water-induced (flux) melting above subduction zones.','The mantle is solid. It melts when pressure drops as it rises, or when water lowers its melting point. Only a small part melts, and that part is basalt.',null,true,3,1,1155) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f043','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Plutonic-volcanic equivalents are granite-rhyolite, granodiorite-dacite, diorite-andesite and gabbro-basalt.','Same chemistry, different cooling speed. Plutonic = slow and coarse; volcanic = fast and fine. Dacite and granodiorite are the pair most often confused.','Goa PSC Assistant Professor Geology 2021',true,3,1,1156) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f044','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','Dolerite (diabase) is the medium-grained hypabyssal equivalent of basalt and gabbro, made of calcic plagioclase and augite, and typically forms dykes and sills.','Hypabyssal = shallow intrusion, between plutonic and volcanic. Medium cooling speed gives medium grain size and ophitic texture.',null,true,3,1,1157) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f045','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of basalts','Basalt consists essentially of calcic plagioclase (labradorite) and augite, with or without olivine; quartz is not an essential mineral.','Basalt is a basic rock (45-52% SiO2), so there is no spare silica to form quartz. Olivine-bearing types are called olivine basalt.','Kerala PSC HSST Geology 2026',true,3,1,1158) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f046','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of basalts','Mid-ocean ridge basalt (MORB) is tholeiitic, low in potassium and depleted in incompatible elements, and forms by decompression melting of depleted upper mantle.','Incompatible elements (K, Rb, light rare earths) prefer melt over crystals. Earlier melting had already removed them from this mantle source.',null,true,3,1,1159) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f047','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of basalts','Ocean island basalts (OIB), as in Hawaii and Réunion, are enriched in incompatible elements and are linked to hotspots fed by mantle plumes.','Plumes tap a deeper, less depleted mantle source than ridges do. So OIB is richer in K and light rare earths than MORB, and often alkaline.',null,true,3,1,1160) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f048','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of basalts','Continental flood basalts are huge piles of mainly tholeiitic lava erupted from fissures in a short time; examples are the Deccan, Siberian, Columbia River and Paraná provinces.','They are large igneous provinces, usually tied to a plume head and often to continental break-up. Fluid basalt spreads as wide flat sheets.',null,true,3,1,1161) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f049','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of basalts','The Deccan Traps are tholeiitic flood basalts covering about 500,000 square km of western and central India, erupted through fissures and forming step-like hills.','Trap comes from a Swedish word for stairs. Flat lava flows weather into terraces, as seen in the Western Ghats of Maharashtra.','Uttarakhand PSC Geology paper 2017 (exam name not shown)',true,3,1,1162) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f050','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of basalts','The main Deccan eruptions took place about 66 million years ago, at the Cretaceous-Palaeogene boundary, when India passed over the Réunion hotspot.','Same time as the dinosaur extinction. The hotspot track runs from the Deccan through the Lakshadweep-Chagos ridge to Réunion island today.','Kerala PSC HSST Geology 2026',true,3,1,1163) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f051','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of basalts','The Rajmahal Traps of Jharkhand, with the Sylhet Traps, are Early Cretaceous basalts about 117 million years old, linked to the Kerguelen hotspot.','Older than the Deccan. Remember: Rajmahal = Kerguelen = Early Cretaceous; Deccan = Réunion = end Cretaceous.','Kerala PSC HSST Geology 2026',true,3,1,1164) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f052','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites','I-type granites come from melting of igneous source rocks, are metaluminous with hornblende, sphene and magnetite, and typify subduction-related (Cordilleran) batholiths.','I = igneous source. The I and S types were defined by Chappell and White in the Lachlan Fold Belt of Australia.',null,true,3,1,1165) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f053','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites','S-type granites form by melting of sedimentary rocks, are peraluminous with muscovite, garnet or cordierite, and typify continental collision belts such as the Himalaya.','S = sedimentary source. Clay-rich sediments are rich in alumina, so the melt grows Al-rich minerals. Crustal melting is called anatexis.',null,true,3,1,1166) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f054','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites','A-type granites are anorogenic, alkali-rich and relatively dry, found in rifts and plate interiors; M-type granites are mantle-derived plagiogranites of island arcs and ophiolites.','A = anorogenic (not linked to mountain building) and alkaline. M = mantle. Rapakivi granites are A-type.',null,true,2,2,1167) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f055','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites','The Malani Igneous Suite of western Rajasthan is Neoproterozoic (about 750 million years old) and dominated by rhyolite with granites; it is India''s largest felsic volcanic province.','Felsic = rich in feldspar and silica. Its granites include the Jalor and Siwana granites. Contrast with the basaltic Deccan.','Kerala PSC HSST Geology 2026',true,3,1,1168) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f056','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites','Younger granites of Kerala include the Ambalavayal and Kalpetta granites of Wayanad and the Munnar granite of Idukki; all are Neoproterozoic intrusions.','They cut the older charnockite and gneiss basement, so they are younger than it. Hook: Wayanad has two (Ambalavayal, Kalpetta), Idukki has Munnar.',null,true,2,2,1169) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f057','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites','Charnockite is an orthopyroxene (hypersthene)-bearing rock of granitic composition, named by T.H. Holland after Job Charnock, whose tombstone in Kolkata is made of it.','Type area: St. Thomas Mount near Chennai. With khondalite it is the main rock of Kerala''s highlands. Its quartz looks greasy and blue-grey.',null,true,3,1,1170) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f058','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of andesites','Andesite is an intermediate volcanic rock (about 57-63% SiO2) made of andesine plagioclase with pyroxene or hornblende, named after the Andes mountains.','It is the volcanic equivalent of diorite. It is often porphyritic, with zoned plagioclase phenocrysts.',null,true,3,1,1171) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f059','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of andesites','Andesites belong to the calc-alkaline series of subduction zones, where water released from the sinking slab lowers the melting point of the overlying mantle wedge.','Water acts like salt on ice: it makes hot mantle melt. The calc-alkaline series is basalt, andesite, dacite, rhyolite, with no iron enrichment.',null,true,3,1,1172) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f060','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of alkaline rocks','Syenite is a plutonic rock dominated by alkali feldspar with little or no quartz, usually with hornblende or biotite; its volcanic equivalent is trachyte.','Think of it as granite without the quartz. It is a silica-saturated rock: no quartz, no feldspathoid.',null,true,3,1,1173) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f061','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of alkaline rocks','Nepheline syenite is a silica-undersaturated plutonic rock of alkali feldspar and nepheline with no quartz; its volcanic equivalent is phonolite.','It is used in glass and ceramics. Indian examples: Kishangarh (Rajasthan) and Sivamalai (Tamil Nadu). Phonolite = clinkstone, it rings when struck.',null,true,3,1,1174) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f062','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of alkaline rocks','Alkaline rocks occur mainly in continental rifts and intraplate hotspots, such as the East African Rift, and form by low-degree partial melting of enriched mantle.','A small amount of melting pulls out mostly the alkalis (Na, K) and volatiles first. So small melt fractions are alkali-rich and silica-poor.',null,true,3,1,1175) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f063','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of alkaline rocks','The Angadimogar syenite of Kasaragod district is a well-known alkaline pluton of Kerala; Peralimala in Kannur district is an alkali granite-syenite body.','Both are in north Kerala and intrude the Precambrian basement. Hook: syenite sits in the northernmost district, Kasaragod.',null,false,1,3,1176) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f064','geological-assistant','geological-assistant-m4','Petrology of gabbros','Gabbro is a plutonic rock of calcic plagioclase and clinopyroxene; norite has orthopyroxene instead, and troctolite is plagioclase plus olivine.','All three are basic plutonic rocks. Only the main mafic mineral changes: augite, hypersthene, or olivine.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,2,2,1177) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f065','geological-assistant','geological-assistant-m4','Petrology of gabbros','The Bushveld Complex of South Africa is the world''s largest layered mafic intrusion and the main source of platinum-group elements (Merensky Reef) and chromite.','Heavy minerals settled in layers on the chamber floor. It is also the classic lopolith and has vanadium-bearing magnetite layers.','UPSC Combined Geo-Scientist Mains 2020 Geology Paper II; UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,3,1,1178) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f066','geological-assistant','geological-assistant-m4','Petrology of gabbros','The Skaergaard intrusion of East Greenland is the classic example of closed-system fractional crystallisation of tholeiitic magma, showing strong iron enrichment.','One batch of magma cooled without refilling, so its layers record the full crystallisation history. Studied by Wager and Deer.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,3,1,1179) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f067','geological-assistant','geological-assistant-m4','Petrology of gabbros','The Stillwater Complex of Montana, USA, is an Archaean layered intrusion mined for palladium and platinum (J-M Reef) and known for its chromite seams.','Hook for the big three: Bushveld = South Africa, Skaergaard = Greenland, Stillwater = USA.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,2,2,1180) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f068','geological-assistant','geological-assistant-m4','Petrology of gabbros','Layered intrusions are built of cumulates (accumulated crystals); cryptic layering is a gradual upward change in mineral composition, and such bodies lie mostly in stable cratons.','Cryptic = hidden: you need chemical analysis to see it. Rhythmic layering is the visible repetition of light and dark bands.','Goa PSC Assistant Geologist 2021',true,2,2,1181) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f069','geological-assistant','geological-assistant-m4','Petrology of gabbros','Mafic (dolerite and gabbro) dykes cutting Kerala''s Precambrian basement trend mainly NNW-SSE to NW-SE; the younger ones are Late Cretaceous-Palaeocene, around Deccan Trap age.','The trend is roughly parallel to the west coast. The dykes record stretching of the crust when India rifted and the Arabian Sea opened.',null,false,2,2,1182) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f070','geological-assistant','geological-assistant-m4','Petrology of kimberlites','Kimberlite is a potassic, volatile-rich ultramafic rock with olivine, phlogopite, pyrope garnet and ilmenite; it occurs in carrot-shaped pipes and is the main primary host of diamond.','Named after Kimberley, South Africa. Volatiles (CO2, H2O) make it erupt explosively, drilling pipes called diatremes.','UPSC Combined Geo-Scientist Mains 2020 Geology Paper II; Uttarakhand PSC Geology paper 2017 (exam name not shown)',true,3,1,1183) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f071','geological-assistant','geological-assistant-m4','Petrology of kimberlites','Kimberlite magma rises from depths greater than about 150 km and carries mantle xenoliths; diamond-bearing pipes are confined to old, thick cratons (Clifford''s rule).','Diamond is stable only at very high pressure. Only cold, thick, ancient continental roots reach that depth.','Goa PSC Assistant Geologist 2021',true,3,1,1184) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f072','geological-assistant','geological-assistant-m4','Petrology of kimberlites','Lamproite is an ultrapotassic, magnesium-rich rock with phlogopite and leucite; it can also carry diamond, as at Argyle in Western Australia.','So kimberlite is not the only diamond host. Lamproite is richer in potassium and poorer in CO2 than kimberlite.',null,true,2,2,1185) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f073','geological-assistant','geological-assistant-m4','Petrology of kimberlites','The Wajrakarur kimberlite field lies in Anantapur district, Andhra Pradesh, in the Eastern Dharwar Craton; its pipes are Mesoproterozoic, about 1100 million years old.','Vajra means diamond. India''s main primary diamond source, however, is the Majhgawan pipe at Panna, Madhya Pradesh.',null,true,3,1,1186) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f074','geological-assistant','geological-assistant-m4','Petrology of anorthosites','Anorthosite is a plutonic rock with more than 90% plagioclase feldspar.','It is almost a one-mineral rock, so its colour index is below 10. The light-coloured highlands of the Moon are anorthosite.','Kerala PSC Junior Petrological Analyst (KMML) 2026',true,3,1,1187) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f075','geological-assistant','geological-assistant-m4','Petrology of anorthosites','Archaean anorthosites are layered and very calcic (bytownite-anorthite); Proterozoic massif-type anorthosites have andesine-labradorite and carry ilmenite-magnetite deposits.','Two ages, two styles. Massif-type bodies are large Proterozoic plutons, often found with charnockitic rocks, and are a source of titanium.','Uttarakhand PSC Geology paper 2017 (exam name not shown)',true,3,1,1188) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f076','geological-assistant','geological-assistant-m4','Petrology of anorthosites','The Sittampundi Complex in Namakkal district, Tamil Nadu, is an Archaean layered anorthosite with chromitite layers and very calcic plagioclase (anorthite).','It is the Indian type example of the Archaean layered kind. Its rocks have been used as a stand-in for lunar highland material.',null,true,3,1,1189) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f077','geological-assistant','geological-assistant-m4','Petrology of anorthosites','Massif-type anorthosites of India include Chilka Lake (Odisha), Bankura (West Bengal) and Oddanchatram (Tamil Nadu); Kerala has the Perinthatta anorthosite in Kannur district.','Most lie in the Eastern Ghats and the Southern Granulite Terrain, the high-grade belts of Proterozoic age.',null,false,2,2,1190) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f078','geological-assistant','geological-assistant-m4','Petrology of carbonatites','Carbonatite is an igneous rock containing more than 50% carbonate minerals such as calcite or dolomite.','It looks like marble but came from magma. Calcite-rich coarse carbonatite is called sovite; dolomite-rich is beforsite.',null,true,3,1,1191) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f079','geological-assistant','geological-assistant-m4','Petrology of carbonatites','Ol Doinyo Lengai in Tanzania is the only active carbonatite volcano and erupts sodium-rich natrocarbonatite lava.','Its lava is very cool and runny for a lava, and looks black, then turns white on weathering. It sits in the East African Rift.',null,true,3,1,1192) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f080','geological-assistant','geological-assistant-m4','Petrology of carbonatites','Carbonatites occur with alkaline rocks such as nepheline syenite and ijolite in ring complexes of continental rifts; the alkali-metasomatised halo around them is called fenite.','Metasomatism = chemical change by hot fluids. Fenite is named after the Fen complex in Norway. Sodium and potassium soak into the wall rock.',null,true,3,1,1193) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f081','geological-assistant','geological-assistant-m4','Petrology of carbonatites','Carbonatites are the chief source of rare earth elements (bastnäsite, as at Bayan Obo and Mountain Pass) and niobium (pyrochlore, as at Araxá).','Carbonatite melt gathers elements that do not fit in common silicate minerals. They also supply phosphate (apatite), fluorite and vermiculite.','Kerala PSC HSST Geology 2026',true,3,1,1194) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f082','geological-assistant','geological-assistant-m4','Petrology of carbonatites','Amba Dongar in Chhota Udepur district, Gujarat, is a carbonatite ring complex of Deccan Trap age that hosts India''s largest fluorite deposit and rare earth minerals.','It formed at the end of Deccan volcanism, about 65 million years ago. Hook: Amba Dongar = fluorite; Sevattur = vermiculite.',null,true,3,1,1195) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f083','geological-assistant','geological-assistant-m4','Petrology of carbonatites','The Sevattur carbonatite in northern Tamil Nadu is Neoproterozoic, mainly dolomitic, and is mined for vermiculite; it also carries apatite and pyrochlore.','It is much older than Amba Dongar. It lies close to the Samalpatti carbonatite, with syenite and pyroxenite around it.',null,true,2,2,1196) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f084','geological-assistant','geological-assistant-m4','Petrology of kimberlites','The Majhgawan pipe near Panna, Madhya Pradesh, mined by NMDC, is India''s main primary diamond source; long called kimberlite, its rock is now often classed as lamproite.','Panna = diamonds. The pipe cuts Vindhyan sandstone of the Bundelkhand region. Lamproite is a potassium-rich cousin of kimberlite that can also carry diamond.',null,false,3,1,1197) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f085','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites','The Closepet Granite of Karnataka is a north-south linear belt, about 400 km long, of potassium-rich granite about 2.5 billion years old (late Archaean) in the Dharwar Craton.','Closepet is the old name of Ramanagara town. The belt runs like a spine through the craton, close to the join between its western and eastern blocks.',null,true,3,1,1198) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f086','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of alkaline rocks','The Sivamalai alkaline complex near Kangayam, Tamil Nadu, is made mainly of nepheline syenite and syenite, some of it corundum-bearing; T.H. Holland named it the ''Sivamalai series'' in 1901.','Nepheline forms only when silica is short, so these rocks have no quartz. Excess alumina with little silica gives corundum (Al2O3).',null,true,2,2,1199) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f087','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites','The type area of charnockite is Pallavaram-St Thomas Mount near Chennai; in Kerala, charnockite is the most widespread basement rock, and patchy ''incipient charnockite'' is seen in southern Kerala quarries.','Type area = the place where a rock was first described. Incipient charnockite means dark greasy patches where gneiss was caught turning into charnockite.',null,true,3,1,1200) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f088','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','On an AFM diagram (alkalis, iron oxide, magnesia), tholeiitic magmas show early iron enrichment (Fenner trend), while calc-alkaline magmas show no iron enrichment (Bowen trend).','Calc-alkaline magmas are wet and oxidised, so magnetite forms early and removes iron. Dry tholeiitic magma keeps its iron in the melt for longer.',null,true,3,1,1201) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f089','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of basalts','Tholeiitic basalt is silica-saturated (hypersthene in the norm) and carries low-calcium pyroxene; alkali basalt is silica-undersaturated (nepheline in the norm) with olivine and titanium-rich augite.','Norm = minerals calculated from the chemistry. Hypersthene in the norm means enough silica; nepheline in the norm means silica is short.',null,true,2,2,1202) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f090','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of andesites','Andesite is typically porphyritic with zoned plagioclase phenocrysts and builds steep composite volcanoes (stratovolcanoes) around the Pacific ''Ring of Fire''.','Andesite lava is sticky and gas-rich, so eruptions are explosive and pile up steep cones of lava and ash. Zoning records changing conditions in the magma chamber.',null,true,2,2,1203) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f091','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites','In the IUGS QAPF diagram, granite has 20-60% quartz among its felsic (light) minerals, with plagioclase forming 10-65% of the total feldspar.','Less than 20% quartz moves the rock towards syenite or monzonite. More plagioclase than 65% of the feldspar makes it granodiorite.',null,true,2,2,1204) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4a-f092','geological-assistant','geological-assistant-m4','Petrology and geotectonic evolution of granites, basalts, andesites and alkaline rocks','By the phase rule (F = C - P + 2), a eutectic or peritectic point of a binary system at fixed pressure has three coexisting phases and zero degrees of freedom (an invariant point).','At fixed pressure the rule becomes F = C - P + 1 = 2 - 3 + 1 = 0. So temperature and liquid composition stay fixed until one phase is used up.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,2,2,1205) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f001','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Metamorphism is the solid-state change in the minerals and texture of a rock caused by changes in temperature, pressure and chemically active fluids.','The rock stays solid. If it melts, the process is no longer metamorphic but igneous (anatexis = partial melting).',null,true,3,1,1206) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f002','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','The three agents of metamorphism are heat, pressure (uniform confining pressure plus directed stress) and chemically active fluids.','Heat drives mineral reactions. Directed stress lines minerals up (foliation). Fluids carry ions and speed reactions up.','UPSC Geologist Exam 2018 Geology Paper II (descriptive)',true,3,1,1207) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f003','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Contact (thermal) metamorphism is caused mainly by heat from an igneous intrusion; the baked zone of country rock around the intrusion is called the contact aureole.','Heat is the main agent and stress is small, so the rocks are usually not foliated. A bigger, hotter intrusion gives a wider aureole.',null,true,3,1,1208) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f004','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Regional (dynamothermal) metamorphism acts over large areas of orogenic belts under both heat and directed pressure, giving foliated rocks such as slate, schist and gneiss.','Mountain building squeezes and heats rocks together. Squeezing makes platy minerals grow parallel, so the rocks split in layers.','Kerala PSC paper 042/2025 (descriptive)',true,3,1,1209) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f005','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Cataclastic (dynamic) metamorphism occurs along fault and shear zones, where rocks are crushed and sheared mechanically with little rise in temperature.','Stress is the main agent here, not heat. Products are fault breccia, cataclasite and mylonite.',null,true,2,2,1210) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f006','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Burial metamorphism occurs at the base of thick sedimentary or volcanic piles without strong deformation and typically produces zeolite-facies minerals.','Only the weight of overlying rock and gentle heat act. So original bedding survives and no foliation forms.',null,true,2,2,1211) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f007','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','Shock (impact) metamorphism is recognised by the very high-pressure silica polymorphs coesite and stishovite and by shatter cones.','A meteorite impact gives extreme pressure for a split second. Ordinary crustal metamorphism cannot make stishovite.','UPSC Geologist Exam 2018 Geology Paper II (descriptive)',true,2,2,1212) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f008','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Retrograde metamorphism (diaphthoresis) changes a high-grade assemblage to a lower-grade one during cooling, for example garnet to chlorite or pyroxene to amphibole.','Low-grade minerals contain water. So retrograde change happens only where water gets back into the rock, usually along shear zones.','UPSC Geologist Mains 2020 Geology Paper II (descriptive)',true,2,2,1213) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f009','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Metamorphic textures are called crystalloblastic: the suffix ''-blastic'' means grown during metamorphism, while the prefix ''blasto-'' marks a relict texture inherited from the parent rock.','Example: porphyroblastic is a new metamorphic texture, but blastoporphyritic is an old igneous porphyritic texture still visible.',null,true,2,2,1214) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f010','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Granoblastic texture is a mosaic of equidimensional grains with no preferred orientation, typical of quartzite, marble, hornfels and granulite.','Quartz, calcite and feldspar are not platy, so they grow as equal-sized grains. Grain boundaries often meet at 120 degree triple junctions.',null,true,3,1,1215) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f011','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Lepidoblastic texture is the parallel arrangement of platy minerals such as muscovite, biotite and chlorite, as seen in mica schist.','Lepido = scale or flake. Flaky micas grow at right angles to the squeezing direction.',null,true,3,1,1216) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f012','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Nematoblastic texture is the parallel arrangement of prismatic or needle-like minerals such as hornblende, actinolite and sillimanite, as in hornblende schist.','Nema = thread. Think of needles lying side by side.',null,true,3,1,1217) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f013','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Porphyroblastic texture has large metamorphic crystals (porphyroblasts) such as garnet or staurolite set in a finer-grained matrix.','It is the metamorphic twin of porphyritic texture. Phenocrysts grow from magma, porphyroblasts grow in solid rock.','IIT-JAM Geology 2019',true,3,1,1218) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f014','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Poikiloblastic (sieve) texture is shown by porphyroblasts crowded with small inclusions of other minerals, common in staurolite, cordierite and garnet.','The fast-growing crystal swallows matrix grains instead of pushing them out. The igneous equivalent is poikilitic.','IIT-JAM Geology 2019',true,3,1,1219) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f015','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Idioblastic crystals show their own crystal faces and xenoblastic crystals do not; garnet, staurolite, sphene and rutile stand high in the crystalloblastic series.','Minerals high in the series (Becke) have strong crystallising force and keep good shapes. Quartz and feldspar stand low and stay shapeless.',null,true,1,3,1220) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f016','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Relict (palimpsest) textures are features of the parent rock that survive metamorphism, for example blastoporphyritic, blastophitic and blastopsammitic textures.','Palimpsest = old writing showing through new writing. They tell us what the parent rock was.',null,true,3,1,1221) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f017','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Mylonitic texture forms in ductile shear zones: grain size is reduced by dynamic recrystallisation, giving a fine foliated matrix around surviving porphyroclasts.','Porphyroclasts are old broken survivors, not new growths like porphyroblasts. Lapworth named mylonite from the Moine Thrust, Scotland.','IIT-JAM Geology 2019',true,3,1,1222) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f018','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Decussate texture is a random criss-cross arrangement of platy or prismatic crystals, typical of contact metamorphic rocks formed without directed stress.','No squeezing means no alignment. Micas in hornfels point in all directions.',null,true,1,3,1223) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f019','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Helicitic texture is curved or S-shaped trails of inclusions inside a porphyroblast; spiral trails in ''snowball'' garnet show growth during deformation (syn-tectonic).','The crystal rotated while it grew, so the trapped foliation is wound up like a rolled snowball.','UPSC Geologist Mains 2020 Geology Paper II (descriptive)',true,2,2,1224) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f020','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Slaty cleavage is the perfect, closely spaced splitting of fine-grained slate, caused by parallel microscopic flakes of mica and chlorite.','The flakes are too small to see, but all lie parallel, so the rock splits into thin sheets. It is usually parallel to fold axial planes.',null,true,3,1,1225) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f021','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Schistosity is foliation formed by parallel, visible flakes of mica or other platy and prismatic minerals in a medium- to coarse-grained rock (schist).','Same cause as slaty cleavage, but higher grade makes the flakes big enough to see with the naked eye.',null,true,3,1,1226) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f022','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Gneissosity (gneissose banding) is the alternation of light quartz-feldspar bands and dark mafic bands; eye-shaped feldspars give augen gneiss.','At high grade, minerals separate into bands (metamorphic segregation). Augen = eyes in German.',null,true,3,1,1227) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f023','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Hornfelsic structure is fine-grained, tough and non-foliated with a granoblastic mosaic; it is typical of contact metamorphism.','Heat without squeezing gives interlocking equal grains. The rock breaks with a splintery, horn-like fracture.','UPSC Geologist Mains 2020 Geology Paper II (descriptive)',true,3,1,1228) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f024','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','With rising grade a shale changes in the order slate, phyllite, schist, gneiss; phyllite is known by its silky sheen.','Mica flakes grow bigger at each step. Sheen in phyllite comes from mica just too fine to see singly.','UPSC Mains 2015 Geology Paper II (descriptive); IIT-JAM Geology 2021',true,3,1,1229) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f025','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Limestone changes to marble and quartz sandstone changes to quartzite; both are granoblastic and normally non-foliated.','They are made of one mineral that is not platy (calcite or quartz). So the grains only recrystallise and enlarge.','IIT-JAM Geology 2019',true,3,1,1230) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f026','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','A basalt changes with rising grade to greenschist, then amphibolite, then basic granulite; under very high pressure it becomes blueschist and eclogite.','Mafic rocks show facies best because their minerals change clearly. Most facies are named after metabasalts.','IIT-JAM Geology 2019',true,3,1,1231) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f027','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','The prefix ''para-'' means a metamorphic rock derived from a sedimentary parent and ''ortho-'' means derived from an igneous parent, as in paragneiss and orthogneiss.','Memory hook: ortho = original igneous. Para = from sediments.',null,true,3,1,1232) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f028','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Pelitic rocks are metamorphosed clay-rich, alumina-rich sediments (shale, mudstone); psammitic rocks come from sandstones and calcareous rocks from limestones and marls.','Pelites are the best grade indicators. Their high alumina lets many index minerals form.',null,true,3,1,1233) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f029','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Barrow''s zones in pelitic rocks of the Scottish Highlands, in order of rising grade, are chlorite, biotite, garnet (almandine), staurolite, kyanite and sillimanite.','Memory hook: ''Can Big Girls Stay Kind Still''. George Barrow mapped them in the Dalradian rocks.','UPSC Mains 2015 Geology Paper II (descriptive); UPSC Geologist Mains 2020 Geology Paper II (descriptive)',true,3,1,1234) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f030','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','An isograd is a line on a map joining points of first appearance of an index mineral; the term was introduced by C. E. Tilley.','Iso = equal, grad = grade. An index mineral is one whose first appearance marks a certain grade.','UPSC Geologist Exam 2018 Geology Paper II (descriptive)',true,3,1,1235) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f031','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Buchan zones (north-east Scotland) are a low-pressure sequence in pelites: biotite, cordierite, andalusite, sillimanite. Kyanite, the marker of the Barrovian type, does not appear.','Andalusite and cordierite are low-pressure minerals. Their presence shows a hotter, shallower crust than in Barrow''s area.','IIT-JAM Geology 2021',true,3,1,1236) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f032','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','In high-grade pelites, muscovite + quartz break down to K-feldspar + sillimanite + water; this marks the second sillimanite (sillimanite-K-feldspar) isograd.','Muscovite cannot survive with quartz at very high temperature. It is a dehydration reaction (water is driven off).','IIT-JAM Geology 2019',true,2,2,1237) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f033','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Grubenmann''s depth zones of metamorphism are the epizone (shallow, low temperature), mesozone (intermediate) and katazone (deep, high temperature).','Old depth-based scheme, later replaced by the facies concept. Epi = upon, meso = middle, kata = down.',null,true,2,2,1238) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f034','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','Harker called kyanite, staurolite and chloritoid ''stress minerals'' and andalusite and cordierite ''anti-stress minerals''.','He thought the first group needs directed stress to form. Today this is explained by pressure-temperature stability, but the terms are still asked.',null,true,2,2,1239) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f035','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Eskola (1915) defined a metamorphic facies as all rocks that reached equilibrium under the same pressure-temperature conditions, so that mineral assemblage depends only on bulk composition.','Same P-T plus same chemistry gives the same minerals. So the minerals tell us the P-T conditions.','UPSC Geologist Mains 2020 Geology Paper II (descriptive)',true,3,1,1240) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f036','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Eskola first named five facies (greenschist, amphibolite, hornfels, sanidinite, eclogite) and later added granulite, epidote-amphibolite and glaucophane-schist (blueschist) facies.','Zeolite and prehnite-pumpellyite facies were added still later by Coombs from New Zealand.',null,true,2,2,1241) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f037','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','The zeolite facies is the lowest-grade facies, marked by zeolites such as laumontite and heulandite; the prehnite-pumpellyite facies comes next.','It bridges diagenesis and true metamorphism. Zeolites are water-rich and break down with only a little more heat.',null,true,2,2,1242) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f038','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Greenschist facies metabasites carry chlorite + actinolite + albite + epidote; the facies represents low-grade regional metamorphism at roughly 300-500 °C.','Chlorite, actinolite and epidote are all green. That gives the rock and the facies their name.',null,true,3,1,1243) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f039','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Amphibolite facies metabasites carry hornblende + plagioclase (more calcic than albite) with or without garnet; it is medium to high grade, roughly 500-700 °C.','The change from greenschist is marked by actinolite turning to hornblende and albite turning to oligoclase-andesine. Epidote-amphibolite facies is the step between.',null,true,3,1,1244) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f040','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Granulite facies is marked by orthopyroxene (hypersthene) with clinopyroxene, plagioclase and often garnet; assemblages are nearly anhydrous and form above about 700 °C.','Hydrous minerals like hornblende and mica break down. Charnockite and khondalite of South India are granulite-facies rocks.','UPSC Geologist Exam 2018 Geology Paper II (descriptive)',true,3,1,1245) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f041','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Blueschist facies is marked by glaucophane with lawsonite (also jadeite + quartz, aragonite); it forms at high pressure and low temperature.','Glaucophane is a blue sodic amphibole. Such cold but deep conditions exist only in subduction zones.','IIT-JAM Geology 2019; IIT-JAM Geology 2020',true,3,1,1246) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f042','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Eclogite is made of omphacite (sodic clinopyroxene) and pyrope-rich garnet, with no plagioclase; it forms from basic rocks at very high pressure.','At high pressure plagioclase is unstable. Its sodium goes into omphacite and its calcium and aluminium into garnet, giving a very dense rock.','IIT-JAM Geology 2020',true,3,1,1247) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f043','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','The contact (low-pressure) facies in order of rising temperature are albite-epidote hornfels, hornblende hornfels, pyroxene hornfels and sanidinite.','They are the low-pressure cousins of greenschist, amphibolite and granulite facies. They form in contact aureoles.','IIT-JAM Geology 2020',true,3,1,1248) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f044','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Sanidinite facies represents very high temperature at very low pressure, seen in xenoliths in basic magma; typical minerals are sanidine, tridymite and mullite.','This is pyrometamorphism (baking by direct contact with lava). Some glass (buchite) may also form.',null,true,2,2,1249) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f045','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Miyashiro''s three facies series (baric types) are low-pressure andalusite-sillimanite type, medium-pressure kyanite-sillimanite (Barrovian) type and high-pressure jadeite-glaucophane type.','Each series is a different geothermal gradient (rate of heating with depth). Abukuma or Buchan is low P, Barrovian is medium P, Sanbagawa or Franciscan is high P.','UPSC Geologist Mains 2020 Geology Paper II (descriptive)',true,3,1,1250) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f046','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','The Al2SiO5 polymorphs kyanite, andalusite and sillimanite coexist at a triple point of about 500 °C and about 0.38 GPa (3.8 kbar) (Holdaway, 1971).','This most-quoted value is a fixed reference point on the P-T grid. Finding all three together pins both pressure and temperature.','IIT-JAM Geology 2019',true,3,1,1251) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f047','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','Among the Al2SiO5 polymorphs, kyanite is the high-pressure form, andalusite the low-pressure low-temperature form, and sillimanite the high-temperature form.','Kyanite is the densest, so pressure favours it. Andalusite is the least dense, so it is found in shallow contact aureoles.',null,true,3,1,1252) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
